/**
 * ۱۲. آخرین نگهبان نور — The Last Guardian of Light
 */
object Story12 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_the_last_guardian_of_light",
        chapters = listOf(
            chapter1(),
            chapter2(),
            chapter3(),
            chapter4(),
            chapter5(),
            chapter6(),
            chapter7(),
        )
    )

    // ─────────── فصل ۱: شهری که خاموش شد ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The City That Went Dark", titlePersian = "شهری که خاموش شد",
        paragraphs = listOf(
            StoryParagraph("Arkadia was a city of light, and its people had never learned to fear the dark.", "آرکادیا شهری از نور بود و مردمش هرگز یاد نگرفته بودند از تاریکی بترسند."),
            StoryParagraph("Its mornings were golden, its noons were bright, and its evenings melted into a soft amber dusk.", "صبح‌هایش طلایی بود، نیمروزهایش روشن، و غروب‌هایش در شفقی کهربایی و نرم آب می‌شد."),
            StoryParagraph("For three hundred years, no one in Arkadia had seen a truly dark night.", "سیصد سال بود که هیچ‌کس در آرکادیا شبی به‌راستی تاریک ندیده بود."),
            StoryParagraph("The sun was always warm, the stars were always bright, and the moon was always full.", "خورشید همیشه گرم بود، ستاره‌ها همیشه درخشان، و ماه همیشه کامل."),
            StoryParagraph("But on the seventh day of the month of Harvest, the sun did not rise.", "اما در روز هفتم از ماه برداشت، خورشید طلوع نکرد."),
            StoryParagraph("At first, the people of Arkadia told themselves it was only a delay.", "اول، مردم آرکادیا به خودشان گفتند فقط تأخیری است."),
            StoryParagraph("They said the sky was sleepy, the stars were late, the moon had turned away.", "گفتند آسمان خواب‌آلوده، ستاره‌ها دیر کرده‌اند، ماه روی برگردانده."),
            StoryParagraph("But noon came, and afternoon came, and still there was no light.", "اما نیمروز آمد و بعدازظهر آمد و هنوز نوری نبود."),
            StoryParagraph("Then the stars began to disappear, one by one, like candles being blown out.", "بعد ستاره‌ها یکی‌یکی شروع به ناپدید شدن کردند، مثل شمع‌هایی که فوت می‌شوند."),
            StoryParagraph("And when the last star died, the people of Arkadia finally understood.", "و وقتی آخرین ستاره مرد، مردم آرکادیا بالاخره فهمیدند."),
            StoryParagraph("Their city had been abandoned by the light.", "شهرشان توسط نور رها شده بود."),
            StoryParagraph("In a small basement beneath an old house, a boy of seventeen sat alone in the dark.", "در زیرزمین کوچکی زیر خانه‌ای قدیمی، پسری هفده‌ساله در تاریکی تنها نشسته بود."),
            StoryParagraph("His name was Arin, and he had been hiding there for three days.", "نامش آرین بود و سه روز بود که آنجا پنهان شده بود."),
            StoryParagraph("Three days without food, three days without light, three days without hope.", "سه روز بدون غذا، سه روز بدون نور، سه روز بدون امید."),
            StoryParagraph("His grandfather had died three years ago, leaving him nothing but grief.", "پدربزرگش سه سال پیش مرده بود و چیزی جز اندوه برایش نگذاشته بود."),
            StoryParagraph("But he had left one thing behind: an old brass lantern with a cracked glass.", "اما یک چیز پشت سر گذاشته بود: فانوسی برنجی و کهنه با شیشه‌ای ترک‌خورده."),
            StoryParagraph("Arin had kept it for three years, never once lighting it.", "آرین سه سال آن را نگه داشته بود، هرگز روشنش نکرده بود."),
            StoryParagraph("It was a memory, not a tool; a relic, not a light.", "خاطره‌ای بود، نه ابزاری؛ یادگاری‌ای بود، نه نوری."),
            StoryParagraph("But on the night the world went dark, the lantern began to glow.", "اما در شبی که جهان تاریک شد، فانوس شروع به درخشیدن کرد."),
            StoryParagraph("It glowed without being lit, without being touched, without any reason at all.", "بدون روشن شدن می‌درخشید، بدون لمس شدن، بدون هیچ دلیلی."),
            StoryParagraph("Its light was not the light of fire or of the sun.", "نورش نور آتش یا خورشید نبود."),
            StoryParagraph("It was older than both, and it was somehow alive.", "از هر دو قدیمی‌تر بود و به‌نحوی زنده بود."),
            StoryParagraph("Arin watched it for a long time, too afraid to move.", "آرین مدت طولانی تماشایش کرد، از ترس اینکه حرکت کند."),
            StoryParagraph("Beside the lantern lay an envelope he had never opened.", "کنار فانوس پاکتی افتاده بود که هرگز بازش نکرده بود."),
            StoryParagraph("It was sealed with wax the color of dried blood.", "با مومی به رنگ خون خشکیده مهر شده بود."),
            StoryParagraph("Arin had seen it a hundred times in three years, and every time he had looked away.", "آرین سه سال آن را صد بار دیده بود و هر بار نگاهش را برگردانده بود."),
            StoryParagraph("He had been afraid of what it might say.", "می‌ترسید از آنچه ممکن بود بگوید."),
            StoryParagraph("But tonight, with the lantern burning in his hand, he found the courage to open it.", "اما امشب، با فانوسی که در دستش می‌سوخت، شجاعت باز کردنش را یافت."),
            StoryParagraph("His hands trembled as he broke the wax and unfolded the letter.", "دست‌هایش می‌لرزید وقتی موم را شکست و نامه را باز کرد."),
            StoryParagraph("Inside was a single sentence, written in his grandfather's hand.", "داخلش جمله‌ای یگانه بود، به خط پدربزرگش."),
            StoryParagraph("\"When every light dies, keep the lantern burning and find the seven guardians.\"", "«وقتی هر نوری مرد، فانوس را روشن نگه دار و هفت نگهبان را پیدا کن.»"),
            StoryParagraph("Arin read it again, and again, and again.", "آرین باز خواندش، و باز، و باز."),
            StoryParagraph("He did not understand it, but he knew he could not ignore it.", "نمی‌فهمیدش، اما می‌دانست نمی‌تواند نادیده‌اش بگیرد."),
            StoryParagraph("From the streets above came strange sounds: whispers, screams, footsteps.", "از خیابان‌های بالا صداهای عجیبی می‌آمد: زمزمه، جیغ، قدم."),
            StoryParagraph("Something was out there in the dark, and it was hungry.", "چیزی آن بیرون در تاریکی بود و گرسنه بود."),
            StoryParagraph("Arin wanted to stay hidden, but the lantern would not let him.", "آرین می‌خواست پنهان بماند، اما فانوس نمی‌گذاشت."),
            StoryParagraph("Its light pulsed in his hand like a heartbeat.", "نورش در دستش مثل ضربان قلب می‌تپید."),
            StoryParagraph("He rose to his feet, and for the first time in his life, he left the basement.", "برخاست و برای نخستین بار در زندگی‌اش از زیرزمین بیرون آمد."),
            StoryParagraph("He stepped into the darkness, holding the lantern high.", "به تاریکی قدم گذاشت و فانوس را بالا نگه داشت."),
            StoryParagraph("He did not know where he was going, but he knew he had to go.", "نمی‌دانست کجا می‌رود، اما می‌دانست باید برود.")
        )
    )
// ─────────── فصل ۲: فانوس و سایه ───────────
private fun chapter2() = StoryChapter(
    number = 2, title = "The Lantern and the Shadow", titlePersian = "فانوس و سایه",
    paragraphs = listOf(
        StoryParagraph("The first street was the hardest.", "اولین خیابان سخت‌ترین بود."),
        StoryParagraph("Arin had lived in Arkadia all his life, but he had never seen it like this.", "آرین تمام عمرش در آرکادیا زندگی کرده بود، اما هرگز آن را این‌گونه ندیده بود."),
        StoryParagraph("The shops were dark, the windows were black, and the doors stood open like empty mouths.", "مغازه‌ها تاریک بودند، پنجره‌ها سیاه، و درها مثل دهان‌های خالی باز ایستاده بودند."),
        StoryParagraph("Every alley seemed to breathe, every shadow seemed to watch.", "هر کوچه انگار نفس می‌کشید، هر سایه انگار تماشا می‌کرد."),
        StoryParagraph("The lantern's light was small, but it was steady.", "نور فانوس کوچک بود، اما ثابت بود."),
        StoryParagraph("It lit a circle of gold around him, no wider than his own two arms.", "دایره‌ای طلایی دور او روشن می‌کرد، پهن‌تر از دو دست خودش نه."),
        StoryParagraph("Beyond that circle, the darkness waited.", "آن‌سوی آن دایره، تاریکی منتظر بود."),
        StoryParagraph("Arin walked slowly, one step at a time, breathing hard.", "آرین آهسته راه رفت، قدمی یکی، به‌سختی نفس می‌کشید."),
        StoryParagraph("He passed a bakery where the bread had turned to stone.", "از نانوایی‌ای گذشت که نان‌هایش سنگ شده بودند."),
        StoryParagraph("He passed a school where the desks sat empty, waiting for children who would never come.", "از مدرسه‌ای گذشت که نیمکت‌هایش خالی نشسته بودند، منتظر بچه‌هایی که هرگز نمی‌آمدند."),
        StoryParagraph("At the edge of the market square, he saw an old woman sitting on a bench.", "لبه‌ی میدان بازار، پیرزنی را روی نیمکتی نشسته دید."),
        StoryParagraph("Her hands were folded in her lap, and her eyes were red with weeping.", "دست‌هایش در دامنش روی هم بود و چشمانش از گریه سرخ."),
        StoryParagraph("She did not look up when he approached, but she spoke before he could.", "وقتی نزدیک شد سر بلند نکرد، اما قبل از او حرف زد."),
        StoryParagraph("\"You carry the old light,\" she said.", "گفت: «تو نور قدیمی را حمل می‌کنی.»"),
        StoryParagraph("Arin stopped. \"How do you know?\" he asked.", "آرین ایستاد. پرسید: «از کجا می‌دانی؟»"),
        StoryParagraph("\"I can feel it,\" she said. \"It is warm, and it is kind, and it is very old.\"", "گفت: «حسش می‌کنم. گرم است و مهربان و بسیار قدیمی.»"),
        StoryParagraph("Her name was Maryam, and she had once been a keeper of the city archives.", "نامش مریم بود و روزگاری نگهبان آرشیو شهر بوده بود."),
        StoryParagraph("She knew the old stories, the forgotten ones, the ones no one else remembered.", "داستان‌های قدیمی را می‌دانست، فراموش‌شده‌ها را، آن‌هایی که هیچ‌کس دیگر به یاد نمی‌آورد."),
        StoryParagraph("\"The guardians are gone,\" she said quietly.", "آرام گفت: «نگهبان‌ها رفته‌اند.»"),
        StoryParagraph("\"What guardians?\" Arin asked.", "آرین پرسید: «چه نگهبان‌هایی؟»"),
        StoryParagraph("\"Seven guardians,\" she said. \"Seven lights that kept the darkness away.\"", "گفت: «هفت نگهبان. هفت نوری که تاریکی را دور نگه می‌داشتند.»"),
        StoryParagraph("\"The Red Guardian of courage, the Orange of warmth, the Yellow of hope.\"", "«نگهبان سرخِ شجاعت، نارنجیِ گرما، زردِ امید.»"),
        StoryParagraph("\"The Green of healing, the Blue of truth, the Violet of dreams.\"", "«سبزِ شفا، آبیِ حقیقت، بنفشِ رؤیا.»"),
        StoryParagraph("\"And the White Guardian of dawn, who was the last and the greatest of them all.\"", "«و نگهبان سفیدِ سپیده‌دم، که آخرین و بزرگ‌ترینشان بود.»"),
        StoryParagraph("Arin sat down beside her, the lantern between them.", "آرین کنارش نشست، فانوس بینشان."),
        StoryParagraph("\"What happened to them?\" he asked.", "پرسید: «چه بر سرشان آمد؟»"),
        StoryParagraph("\"A thing called Diozen came from beneath the world,\" she said.", "گفت: «چیزی به نام دیوژن از زیر جهان آمد.»"),
        StoryParagraph("\"He hates light, because light reveals what he truly is.\"", "«از نور متنفر است، چون نور نشان می‌دهد او واقعاً چیست.»"),
        StoryParagraph("\"He took the guardians one by one, and imprisoned them in his fortress.\"", "«نگهبان‌ها را یکی‌یکی گرفت و در قلعه‌اش زندانی کرد.»"),
        StoryParagraph("\"Six of them are lost. Only one remains, but he sleeps.\"", "«شش‌تایشان گم شده‌اند. فقط یکی مانده، اما او می‌خوابد.»"),
        StoryParagraph("\"Where does he sleep?\" Arin asked.", "آرین پرسید: «کجا می‌خوابد؟»"),
        StoryParagraph("\"In the Silent Tower, beyond the mountains,\" she said. \"But only true light can wake him.\"", "گفت: «در برج خاموش، آن‌سوی کوه‌ها. اما فقط نور راستین می‌تواند بیدارش کند.»"),
        StoryParagraph("Arin looked at the lantern in his hands.", "آرین به فانوس در دستانش نگاه کرد."),
        StoryParagraph("\"Is this true light?\" he asked.", "پرسید: «این نور راستین است؟»"),
        StoryParagraph("\"It is a spark of it,\" she said. \"The rest must come from you.\"", "گفت: «جرقه‌ای از آن است. بقیه‌اش باید از تو بیاید.»"),
        StoryParagraph("A howl rose from the far end of the square.", "زوزه‌ای از انتهای میدان بلند شد."),
        StoryParagraph("The shadows on the rooftops began to move.", "سایه‌های روی پشت‌بام‌ها شروع به حرکت کردند."),
        StoryParagraph("Maryam stood up quickly and grabbed his arm.", "مریم سریع بلند شد و بازویش را گرفت."),
        StoryParagraph("\"Go,\" she said. \"Do not let them take the lantern.\"", "گفت: «برو. نگذار فانوس را بگیرند.»"),
        StoryParagraph("\"What about you?\" he asked.", "پرسید: «تو چه؟»"),
        StoryParagraph("\"I have lived long enough,\" she said. \"Now go.\"", "گفت: «به‌قدر کافی زندگی کرده‌ام. حالا برو.»"),
        StoryParagraph("Arin ran.", "آرین دوید.")
    )
)
// ─────────── فصل ۳: جاده‌ی سکوت ───────────
private fun chapter3() = StoryChapter(
    number = 3, title = "The Road of Silence", titlePersian = "جاده‌ی سکوت",
    paragraphs = listOf(
        StoryParagraph("Arin walked through the night, and the night refused to end — as though time itself had grown weary of turning and had settled, sullen and motionless, over the dying world.", "آرین شب را به راه رفتن گذراند، و شب از پایان یافتن سر باز زد — گویی خودِ زمان از چرخیدن خسته شده و بر جهان مُرده، گرفته و بی‌حرکت، نشسته بود."),
        StoryParagraph("There was no dawn to greet him, no sun to warm the marrow of his bones; there was only the lantern, and the road, and the silence that had learned to speak in whispers.", "سپیده‌دەمی نبود که به استقبالش آید، خورشیدی نبود که مغز استخوانش را گرم کند؛ فقط فانوس بود، و جاده، و سکوتی که آموخته بود با زمزمه حرف بزند."),
        StoryParagraph("His feet blistered within the first hour. His stomach ached with a hunger that had passed beyond complaint into a kind of numb, patient surrender.", "پاهایش در همان ساعت نخست تاول زد. شکمش از گرسنگی‌ای درد گرفت که از شکایت فراتر رفته و به نوعی تسلیم کُند و صبور رسیده بود."),
        StoryParagraph("By the time the sky — if such a black and lidless thing could still be called a sky — began to pale with the promise of a morning that did not come, he had reached the foothills.", "تا زمانی که آسمان — اگر چنین چیز سیاه و بی‌پلک را هنوز بتوان آسمان نامید — شروع به رنگ‌پریده شدن کرد با وعده‌ی صبحی که نیامد، او به دامنه‌ها رسیده بود."),
        StoryParagraph("The mountains rose around him like the vertebrae of some vast and slumbering beast, ancient beyond reckoning, indifferent beyond mercy.", "کوه‌ها دورش بلند شده بودند مثل مهره‌های ستون فقرات جانوری عظیم و خفته، کهن‌تر از آنچه بتوان شمرد، بی‌اعتنا فراتر از رحم."),
        StoryParagraph("He stopped beside a stream that had frozen solid, its waters arrested mid-course like a sentence left unfinished.", "کنار جویباری ایستاد که کاملاً یخ بسته بود، آب‌هایش در میانه‌ی راه متوقف مثل جمله‌ای که ناتمام رها شده."),
        StoryParagraph("When he held the lantern above the ice, the surface glittered as if it remembered sunlight — as if the memory of warmth, imprisoned in the crystal lattice, were still waiting to be released.", "وقتی فانوس را بالای یخ گرفت، سطحش چنان درخشید که گویی نور خورشید را به یاد می‌آورد — گویی خاطره‌ی گرما، در قفس بلورین زندانی، هنوز منتظر آزاد شدن بود."),
        StoryParagraph("A voice — sharp, unwelcome, and unmistakably human — cut through the silence like a blade through silk.", "صدایی — تیز، ناخوانده و بی‌گمان انسانی — سکوت را مثل تیغی از میان ابریشم برید."),
        StoryParagraph("\"You're not from the mountains,\" the voice said, and it carried within it the particular certainty of someone who had learned to read strangers the way she had learned to read weather.", "«تو اهل کوهستان نیستی،» صدا گفت و در خود آن یقین خاصی را داشت که کسی که غریبه‌ها را همان‌طور خوانده که هوا را خوانده بود، دارد."),
        StoryParagraph("Arin turned — slowly, because his body had grown wary of sudden movements — and saw a girl standing behind a pine tree, arms crossed, chin lifted, as though she had been standing there for hours and had merely chosen, until now, to remain unseen.", "آرین چرخید — آهسته، چون بدنش از حرکات ناگهانی محتاط شده بود — و دختری دید که پشت درخت کاج ایستاده بود، دست‌ها روی هم، چانه بالا، گویی ساعت‌ها آنجا ایستاده بود و فقط تا این لحظه انتخاب کرده بود دیده نشود."),
        StoryParagraph("She was about his age, and her hair was braided with a severity that suggested she had no patience for adornment; a fresh cut ran the length of her cheekbone, red and unhealed.", "هم‌سن خودش بود و موهایش با خشونتی بافته شده بود که نشان می‌داد صبری برای زیور ندارد؛ خراشی تازه در امتداد استخوان گونه‌اش می‌دوید، سرخ و التیام‌نیافته."),
        StoryParagraph("A short sword hung at her hip — not a decorative blade, but a working one, with a hilt worn smooth by hands that had used it more than once.", "شمشیری کوتاه به کمرش آویزان بود — نه تیغی تزئینی، بلکه تیغی کاربردی، با دسته‌ای که توسط دست‌هایی که بیش از یک بار استفاده‌اش کرده بودند، صاف و صیقلی شده بود."),
        StoryParagraph("\"I'm looking for the Silent Tower,\" Arin said, and he said it without explanation, because the way she looked at him suggested that explanations would be treated as excuses.", "«دنبال برج خاموش می‌گردم،» آرین گفت و بی توضیح گفت، چون شیوه‌ی نگاه کردنش به او نشان می‌داد توضیح‌ها به‌عنوان بهانه تلقی خواهند شد."),
        StoryParagraph("\"So am I,\" she said — and her eyes narrowed, not with suspicion exactly, but with the wary precision of someone who had learned that first impressions were usually lies.", "«من هم،» گفت — و چشمانش باریک شد، نه دقیقاً از شک، بلکه با دقت احتیاطی کسی که آموخته بود برداشت اول معمولاً دروغ است."),
        StoryParagraph("Her name was Sara. Her father had been the Blue Guardian — the keeper of truth — and he had vanished on the night the lights went out, swallowed by a darkness that had evidently been waiting for him longer than anyone knew.", "نامش سارا بود. پدرش نگهبان آبی بوده — نگهبان حقیقت — و در شبی که نورها خاموش شدند ناپدید شده بود، بلعیده توسط تاریکی‌ای که آشکارا بیش از آنچه کسی می‌دانست منتظرش بود."),
        StoryParagraph("\"My father told me stories about the tower,\" she said, and here — for the first time — something in her voice softened, as if the memory of being told stories were the last warm thing she had managed to preserve.", "«پدرم برایم از برج داستان‌ها می‌گفت،» گفت، و اینجا — برای نخستین بار — چیزی در صدایش نرم شد، گویی خاطره‌ی داستان شنیدن، آخرین چیز گرمی بود که توانسته بود حفظ کند."),
        StoryParagraph("\"He said the White Guardian can see the future — that he saw Diozen coming, years before anyone else, and spent those years preparing, alone, for a war he knew he could not win.\"", "«می‌گفت نگهبان سفید می‌تواند آینده را ببیند — که دیوژن را در حال آمدن دید، سال‌ها پیش از هر کس دیگری، و آن سال‌ها را تنها صرف آماده شدن برای جنگی کرد که می‌دانست نمی‌تواند ببردش.»"),
        StoryParagraph("Arin showed her the lantern and the letter — showed them without hesitation, which was itself a decision, since showing was either the beginning of trust or the end of wisdom.", "آرین فانوس و نامه را نشانش داد — بدون تردید نشانشان داد، که این خودش تصمیمی بود، چون نشان دادن یا آغاز اعتماد بود یا پایان خرد."),
        StoryParagraph("Sara read the sentence twice — slowly, moving her lips as if tasting each word — and then handed it back with a look that suggested she had found in it something she had not expected.", "سارا جمله را دو بار خواند — آهسته، لب‌هایش را حرکت می‌داد گویی هر کلمه را می‌چشد — و بعد با نگاهی پسش داد که نشان می‌داد چیزی در آن یافته که انتظارش را نداشت."),
        StoryParagraph("\"Your grandfather knew something,\" she said at last, and the words landed between them with the weight of a verdict.", "«پدربزرگت چیزی می‌دانسته،» بالاخره گفت و کلمات با وزن حکمی میانشان فرود آمدند."),
        StoryParagraph("\"He never told me,\" Arin said — and the words came out more bitter than he had intended, because they had been sitting inside him for three years, gathering a weight that had, until now, been invisible.", "«هرگز به من نگفت،» آرین گفت — و کلمات تلخ‌تر از آنچه قصد کرده بود بیرون آمدند، چون سه سال درونش نشسته بودند و وزنی جمع کرده بودند که تا حالا نامرئی بود."),
        StoryParagraph("\"Maybe he couldn't,\" Sara replied — and she said it not to comfort him, but as a simple statement of fact, the way she might have remarked upon the coldness of the air.", "«شاید نمی‌توانست،» سارا پاسخ داد — و آن را نه برای تسلی دادن گفت، بلکه به‌عنوان بیان ساده‌ی حقیقت، همان‌طور که ممکن بود سردی هوا را ذکر کند."),
        StoryParagraph("\"Some truths are too heavy for words,\" she continued. \"And some truths are too heavy even for the people who carry them. Perhaps your grandfather was one of those people.\"", "«بعضی حقایق برای کلمات زیادی سنگین‌اند،» ادامه داد. «و بعضی حقایق حتی برای کسانی که حملشان می‌کنند زیادی سنگین‌اند. شاید پدربزرگ تو یکی از همان آدم‌ها بود.»"),
        StoryParagraph("They walked together after that — not because they had decided to trust each other, but because the road was safer with two, and safety, at that particular moment, was worth more than trust.", "بعد از آن با هم راه رفتند — نه چون تصمیم گرفته بودند به هم اعتماد کنند، بلکه چون جاده با دو نفر امن‌تر بود، و امنیت در آن لحظه‌ی خاص، از اعتماد ارزشمندتر بود."),
        StoryParagraph("Sara explained what she knew about the guardians — which was, as it turned out, more than anyone else alive, though still less than she would have needed to feel, in any meaningful sense, prepared.", "سارا توضیح داد چه چیزهایی درباره نگهبان‌ها می‌داند — که معلوم شد، بیش از هر کس زنده‌ی دیگری، هرچند هنوز کمتر از آنچه لازم داشت تا به معنای واقعی کلمه، آماده حس کند."),
        StoryParagraph("Each guardian, she said, had been bound to a color, a weapon, and a duty — and each of them, in the end, had been undone by the very quality that had once made them strong.", "هر نگهبان، گفت، به رنگی و سلاحی و وظیفه‌ای بسته شده بود — و هر یک از آن‌ها، در نهایت، توسط همان کیفیتی نابود شده بود که روزی قویشان کرده بود."),
        StoryParagraph("The Red Guardian, whose courage had once led armies, had been betrayed by the very soldiers he had trusted — and now burned with a shame that no fire could purge.", "نگهبان سرخ، که شجاعتش روزی ارتش‌ها را رهبری کرده بود، توسط همان سربازانی که به آن‌ها اعتماد داشت خیانت دیده بود — و حالا با شرمی می‌سوخت که هیچ آتشی نمی‌توانست پاکش کند."),
        StoryParagraph("The Orange Guardian, whose warmth had once healed the coldest of winters, had been trapped in a fire she could not extinguish — a fire born of the very love she had given so freely.", "نگهبان نارنجی، که گرمی‌اش روزی سردترین زمستان‌ها را شفا داده بود، در آتشی گرفتار شده بود که نمی‌توانست خاموشش کند — آتشی زاده‌ی همان عشقی که این‌قدر سخاوتمندانه بخشیده بود."),
        StoryParagraph("The Yellow Guardian, whose hope had once carried cities through their darkest nights, had been blinded by a light that showed only lies — until hope itself had become a torture.", "نگهبان زرد، که امیدش روزی شهرها را از تاریک‌ترین شب‌هایشان عبور داده بود، با نوری کور شده بود که فقط دروغ نشان می‌داد — تا خودِ امید به شکنجه‌ای بدل شد."),
        StoryParagraph("The Green Guardian, whose hands had once closed wounds no physician could close, had been poisoned by a wound that would not heal — a wound of the spirit, which no herb or herb-lore could touch.", "نگهبان سبز، که دست‌هایش روزی زخم‌هایی را بسته بود که هیچ طبیبی نمی‌توانست، با زخمی مسموم شده بود که التیام نمی‌یافت — زخمی روحی، که هیچ گیاه یا گیاه‌شناسی نمی‌توانست لمسش کند."),
        StoryParagraph("The Blue Guardian — Sara's father — whose voice had once spoken truths so pure that tyrants trembled, had been silenced by a truth he could not speak — a truth so terrible that its mere existence in his mind had become a prison.", "نگهبان آبی — پدر سارا — که صدایش روزی حقیقت‌هایی چنان خالص گفته بود که مستبدان می‌لرزیدند، با حقیقتی سکوت شده بود که نمی‌توانست بگوید — حقیقتی چنان هولناک که خودِ وجودش در ذهنش به زندانی بدل شده بود."),
        StoryParagraph("The Violet Guardian, whose dreams had once painted futures brighter than any reality, had been lost in a dream from which she could not wake — a dream so beautiful that waking had become, to her, the only true nightmare.", "نگهبان بنفش، که رؤیاهایش روزی آینده‌هایی روشن‌تر از هر واقعیتی نقاشی کرده بود، در رؤیایی گم شده بود که نمی‌توانست از آن بیدار شود — رؤیایی چنان زیبا که بیدار شدن، برای او، به تنها کابوس راستین بدل شده بود."),
        StoryParagraph("Only the White Guardian remained free — but he slept, cursed into an endless slumber by Diozen himself, and no power on earth could wake him but the truest of lights.", "فقط نگهبان سفید آزاد مانده بود — اما می‌خوابید، توسط خودِ دیوژن به خوابی بی‌پایان نفرین شده بود، و هیچ قدرتی در زمین نمی‌توانست بیدارش کند جز راستین‌ترین نورها."),
        StoryParagraph("\"So we must wake him,\" Arin said — and the words sounded, even to his own ears, like a sentence of exile pronounced upon himself.", "«پس باید بیدارش کنیم،» آرین گفت — و کلمات، حتی به گوش خودش، مثل حکم تبعیدی به نظر می‌رسید که بر خودش صادر کرده بود."),
        StoryParagraph("\"And then free the others,\" Sara added — and she said it without flinching, because she had long since made peace with the fact that fear and action could, if necessary, coexist.", "«و بعد بقیه را آزاد کنیم،» سارا اضافه کرد — و بدون تزلزل گفت، چون مدتها پیش با این واقعیت کنار آمده بود که ترس و عمل، در صورت لزوم، می‌توانند همزمان وجود داشته باشند."),
        StoryParagraph("They walked for hours without speaking — not because there was nothing to say, but because there was too much, and words, in the face of such immensity, would only have diminished it.", "ساعت‌ها بی‌حرف راه رفتند — نه چون چیزی برای گفتن نبود، بلکه چون چیزهای زیادی بود، و کلمات در برابر چنین عظمتی، تنها می‌توانستند کوچکش کنند."),
        StoryParagraph("The road grew narrow and steep, and the air grew thin and cold, and the silence grew heavier with every mile.", "راه باریک و شیب‌دار شد و هوا نازک و سرد و سکوت با هر مایل سنگین‌تر شد."),
        StoryParagraph("Once, Arin stumbled over a stone he had not seen, and for one terrible moment, the lantern slipped from his hand and hung above the void of the mountainside.", "یک بار، آرین روی سنگی که ندیده بود لغزید و برای یک لحظه‌ی هولناک، فانوس از دستش لغزید و بالای خلاً دامنه‌ی کوه آویزان شد."),
        StoryParagraph("Sara caught his arm before he fell — her grip firm, her face pale, her eyes blazing with something that was not quite anger and not quite fear.", "سارا قبل از افتادن بازویش را گرفت — گرفتنش محکم، چهره‌اش رنگ‌پریده، چشمانش با چیزی می‌سوخت که نه دقیقاً خشم بود و نه دقیقاً ترس."),
        StoryParagraph("\"Careful,\" she said, and her voice was low and tight. \"That lantern is the only light we have left in this world.\"", "«حواس‌ت باشه،» گفت و صدایش آهسته و فشرده بود. «آن فانوس تنها نوری است که در این جهان برایمان مانده.»"),
        StoryParagraph("\"No,\" Arin said — and he surprised himself with the steadiness of his own voice. \"It's not. We have each other.\"", "«نه،» آرین گفت — و خودش هم از ثبات صدای خودش متعجب شد. «این‌طور نیست. ما همدیگر را داریم.»"),
        StoryParagraph("Sara looked at him for a long, unreadable moment — and then, for the first time since he had met her, she smiled: a small, cautious, utterly genuine smile that seemed to cost her something she had not expected to spend.", "سارا لحظه‌ای طولانی و ناخوانا نگاهش کرد — و بعد، برای نخستین بار از وقتی ملاقاتش کرده بود، لبخند زد: لبخندی کوچک، محتاط و کاملاً اصیل که به نظر می‌رسید چیزی برایش هزینه داشت که انتظار پرداختش را نداشت."),
        StoryParagraph("That night, they camped in the hollow of a fallen tree — a shelter so humble that even the wind seemed to pass it by out of pity.", "آن شب در گودی درختی افتاده اردو زدند — پناهگاهی چنان فروتن که حتی باد هم از سر ترحم از کنارش می‌گذشت."),
        StoryParagraph("The lantern glowed between them like a small, stubborn star — the only warmth in a world that had forgotten warmth.", "فانوس بینشان درخشید مثل ستاره‌ای کوچک و سرسخت — تنها گرمای جهانی که گرما را فراموش کرده بود."),
        StoryParagraph("They slept in shifts — one awake, one asleep — and neither of them, when morning finally came, remembered having dreamed at all.", "شیفتی خوابیدند — یکی بیدار، یکی خفته — و هیچ‌کدام، وقتی صبح بالاخره رسید، به یاد نیاورد که خواب دیده باشد."),
        StoryParagraph("And in the morning — or in what should have been morning — they saw, for the first time, the tower.", "و در صبح — یا در آنچه باید صبح می‌بود — برای نخستین بار برج را دیدند.")
    )
)
// ─────────── فصل ۴: برج خاموش ───────────
private fun chapter4() = StoryChapter(
    number = 4, title = "The Silent Tower", titlePersian = "برج خاموش",
    paragraphs = listOf(
        StoryParagraph("On the fourth day, they saw the tower — and the tower, had it possessed eyes, would have seen them coming from miles away, for the lantern in Arin's hand was the only light in a world that had been stripped of every other.", "روز چهارم، برج را دیدند — و برج، اگر چشمی داشت، از مایل‌ها دورتر آمده‌شان را می‌دید، چون فانوس در دست آرین تنها نور جهانی بود که از هر نور دیگری تهی شده بود."),
        StoryParagraph("It rose from the peak of the highest mountain like a finger pointed in accusation at a sky that had forgotten how to shine.", "از قله‌ی بلندترین کوه بلند می‌شد مثل انگشتی که به اتهام به آسمانی اشاره می‌کرد که درخشیدن را فراموش کرده بود."),
        StoryParagraph("The tower was black — but not black with shadow, as one might have expected; black with age, with weariness, with the accumulated gravity of centuries that had never once known ease.", "برج سیاه بود — اما نه سیاه از سایه، آن‌گونه که ممکن بود انتظار داشت؛ سیاه از قدمت، از خستگی، از جاذبه‌ی انباشته‌ی قرن‌هایی که هرگز آسودگی را نشناخته بودند."),
        StoryParagraph("Its stones were so old that they seemed to have absorbed every night the world had ever known — every grief, every silence, every unspoken prayer whispered into the dark by those who had no one else to tell.", "سنگ‌هایش آن‌قدر قدیمی بودند که انگار هر شبی را که جهان شناخته بود جذب کرده بودند — هر اندوه، هر سکوت، هر دعای ناگفته‌ای که در تاریکی توسط کسانی که کس دیگری برای گفتن نداشتند زمزمه شده بود."),
        StoryParagraph("At the base of the tower, a door stood open — not flung open, not broken open, but simply open, as though someone had left it that way for them, and had been waiting a very long time for them to arrive.", "در پای برج، دری باز بود — نه کوبیده باز، نه شکسته باز، بلکه صرفاً باز، گویی کسی آن را برایشان به آن حال گذاشته بود، و مدتی بسیار طولانی منتظر رسیدنشان مانده بود."),
        StoryParagraph("\"That's not comforting,\" Sara said, and her voice, though steady, had acquired a quality that Arin had not heard in it before — the flat, deliberate calm of someone who was choosing courage because the alternative had become unaffordable.", "«این تسلی‌بخش نیست،» سارا گفت و صدایش، هرچند ثابت، به کیفیتی رسیده بود که آرین پیش‌تر در آن نشنیده بود — آرامش تخت و عامدانه‌ی کسی که شجاعت را انتخاب می‌کرد چون گزینه‌ی دیگر غیرقابل تحمل شده بود."),
        StoryParagraph("\"No,\" Arin agreed, and his own voice, when he heard it, surprised him with its steadiness. \"It's not.\"", "«نه،» آرین موافقت کرد و صدای خودش، وقتی شنیدش، از ثباتش متعجبش کرد. «نیست.»"),
        StoryParagraph("They stepped inside, and the air within the tower was cold — not the cold of winter, but the cold of things that had been kept apart from warmth so long that they had forgotten it was ever a possibility.", "داخل شدند و هوای درون برج سرد بود — نه سرمای زمستان، بلکه سرمای چیزهایی که آن‌قدر طولانی از گرما جدا نگاه داشته شده بودند که فراموش کرده بودند هرگز امکانی بوده است."),
        StoryParagraph("The only sound was the soft crackle of the lantern's flame — a sound so small that in any other place it would have been lost entirely, but here, in the absolute silence of the tower, it seemed almost deafening.", "تنها صدا، ترق‌ترق ملایم شعله‌ی فانوس بود — صدایی چنان کوچک که در هر جای دیگری کاملاً گم می‌شد، اما اینجا، در سکوت مطلق برج، تقریباً کرکننده به نظر می‌رسید."),
        StoryParagraph("A spiral staircase wound upward into darkness — not a staircase that climbed, exactly, but one that seemed to unwind, as though the tower itself were a spool of stone and they its patient, unraveling thread.", "پله‌ای مارپیچ به سمت تاریکی بالا می‌رفت — نه دقیقاً پله‌ای که بالا می‌رود، بلکه یکی که به نظر می‌رسید باز می‌شود، گویی خود برج قرقره‌ای سنگی بود و آن‌ها رشته‌ی صبور و بازشونده‌اش."),
        StoryParagraph("They began to climb — Arin first, Sara behind him, and the lantern, held above them both, throwing its small and stubborn circle of gold upon the walls.", "شروع به بالا رفتن کردند — آرین اول، سارا پشت سرش، و فانوس، بالای هر دویشان گرفته، دایره‌ی کوچک و سرسخت طلایی‌اش را روی دیوارها می‌انداخت."),
        StoryParagraph("The stairs creaked beneath their feet — not with the ordinary creak of wood or stone under weight, but with something closer to a murmur, as though the tower were speaking to itself in a language older than speech.", "پله‌ها زیر پاهایشان جیرجیر می‌کردند — نه با جیرجیر معمولی چوب یا سنگ زیر وزن، بلکه با چیزی نزدیک‌تر به زیرلب‌گویی، گویی برج با خودش به زبانی کهن‌تر از گفتار حرف می‌زد."),
        StoryParagraph("On the first landing, they found a mosaic of the seven guardians — each figure rendered in colored stone so fine that it seemed almost alive, almost breathing.", "روی نخستین پاگرد، موزاییکی از هفت نگهبان یافتند — هر پیکره در سنگ رنگی‌ای چنان نازک نقش بسته بود که تقریباً زنده به نظر می‌رسید، تقریباً نفس‌کشنده."),
        StoryParagraph("Each guardian held a weapon, and each weapon glowed with a different color — red, orange, yellow, green, blue, violet.", "هر نگهبان سلاحی در دست داشت و هر سلاح با رنگی متفاوت می‌درخشید — سرخ، نارنجی، زرد، سبز، آبی، بنفش."),
        StoryParagraph("But the White Guardian's face had been chiseled away — deliberately, methodically, with a patience that suggested not vandalism but erasure, as though someone had been determined to ensure that no one would ever know what the last guardian looked like.", "اما صورت نگهبان سفید تراشیده شده بود — عامدانه، روشمند، با صبری که نه خرابکاری بلکه محو را می‌رساند، گویی کسی مصمم شده بود که هیچ‌کس هرگز نداند آخرین نگهبان چه شکلی بوده است."),
        StoryParagraph("\"Someone didn't want us to know his face,\" Sara said, and her hand moved unconsciously to the hilt of her sword.", "«کسی نمی‌خواست چهره‌اش را بشناسیم،» سارا گفت و دستش ناخودآگاه به دسته‌ی شمشیرش رفت."),
        StoryParagraph("\"Or wanted us to fear his face before we ever saw it,\" Arin replied, and the words, as soon as he had spoken them, felt more true than he had intended.", "«یا می‌خواست پیش از آنکه چهره‌اش را ببینیم، از آن بترسیم،» آرین پاسخ داد و کلمات، به‌محض گفتن، راست‌تر از آنچه قصد کرده بود حس شدند."),
        StoryParagraph("They continued upward, past paintings that seemed to watch them, past statues whose heads turned slowly in the corners of their vision, past doorways that opened onto rooms they could not enter.", "به بالا ادامه دادند، از کنار نقاشی‌هایی که به نظر می‌رسید تماشایشان می‌کنند، مجسمه‌هایی که در گوشه‌ی دیدشان آهسته سر می‌گرداندند، و چارچوب‌هایی که به اتاق‌هایی باز می‌شدند که نمی‌توانستند وارد شوند."),
        StoryParagraph("On the second landing, they found a room full of broken mirrors — each shard reflecting a different version of them, a different possibility, a different life they might have lived.", "روی پاگرد دوم، اتاقی پر از آینه‌های شکسته یافتند — هر تکه نسخه‌ای متفاوت از آن‌ها را منعکس می‌کرد، امکانی متفاوت، زندگی‌ای متفاوت که شاید می‌توانستند بزیند."),
        StoryParagraph("In one mirror, Arin was younger — still a child, still unaware of what was coming.", "در یک آینه، آرین جوان‌تر بود — هنوز بچه، هنوز ناآگاه از آنچه در راه بود."),
        StoryParagraph("In another, he was older — haggard, gray, alone, standing over a grave he could not name.", "در دیگری، پیرتر بود — خسته، خاکستری، تنها، بالای گوری ایستاده که نمی‌توانست نامش را ببرد."),
        StoryParagraph("In a third, he was dead — a body on a battlefield, unwept and unremembered.", "در سومی، مرده بود — جسدی بر میدان جنگی، بی‌سوگ و بی‌یاد."),
        StoryParagraph("\"Don't look too long,\" Sara warned, and her own voice was strained. \"Mirrors lie. They show what we fear, not what will be.\"", "«زیاد نگاه نکن،» سارا هشدار داد و صدای خودش هم فشرده بود. «آینه‌ها دروغ می‌گویند. آنچه می‌ترسیم را نشان می‌دهند، نه آنچه خواهد بود.»"),
        StoryParagraph("But Arin, as he turned away, could not shake the memory of his own dead face — and the suspicion, creeping, unwelcome, that somewhere among the broken fragments had been the truth.", "اما آرین، در حالی که روی می‌گرداند، نمی‌توانست خاطره‌ی چهره‌ی مرده‌ی خودش را از خود براند — و آن گمان که خزنده و ناخوانده می‌آمد که جایی میان تکه‌های شکسته، حقیقت بوده است."),
        StoryParagraph("On the third landing, the shadows attacked — and this time, they did not keep their distance.", "روی پاگرد سوم، سایه‌ها حمله کردند — و این بار، فاصله نگرفتند."),
        StoryParagraph("They came from the walls, from the ceiling, from the floor, from the air itself — shapeless and hungry and utterly without mercy.", "از دیوارها آمدند، از سقف، از کف، از خود هوا — بی‌شکل و گرسنه و کاملاً بی‌رحم."),
        StoryParagraph("Arin raised the lantern, and Sara raised her sword, and together they fought — not as heroes in a story, but as two frightened children in a place where courage had become, simply, the only option that permitted them to continue breathing.", "آرین فانوس را بالا برد و سارا شمشیرش را و با هم جنگیدند — نه به‌عنوان قهرمانان داستان، بلکه به‌عنوان دو بچه‌ی ترسیده در جایی که شجاعت، به‌سادگی، به تنها گزینه‌ای بدل شده بود که اجازه می‌داد نفس کشیدن را ادامه دهند."),
        StoryParagraph("The lantern burned brighter with each strike — as though it drew its light from the very darkness it was destroying, as though every shadow unmade were fuel for the flame.", "فانوس با هر ضربه روشن‌تر می‌سوخت — گویی نورش را از همان تاریکی‌ای که نابود می‌کرد می‌کشید، گویی هر سایه‌ی برچیده‌شده سوختی برای شعله بود."),
        StoryParagraph("Sara's sword sang through the air — sharp, precise, relentless — and where it struck, the shadows screamed and dissolved like smoke in wind.", "شمشیر سارا در هوا آواز خواند — تیز، دقیق، بی‌امان — و هر جا می‌زد، سایه‌ها جیغ می‌کشیدند و مثل دود در باد حل می‌شدند."),
        StoryParagraph("When the last shadow fell, Sara was bleeding — a long cut along her arm, red and deep and dangerous.", "وقتی آخرین سایه افتاد، سارا خون‌آلود بود — خراشی بلند در امتداد بازویش، سرخ و عمیق و خطرناک."),
        StoryParagraph("Arin pressed the lantern to her wound, and the light — patient, ancient, impossibly gentle — sealed the skin as though the cut had never been.", "آرین فانوس را روی زخمش گذاشت و نور — صبور، کهن، به‌طرز غیرممکنی ملایم — پوست را بست گویی خراش هرگز نبوده."),
        StoryParagraph("\"The lantern heals,\" Sara whispered, and there was wonder in her voice, and behind the wonder, something else — a fear that such power existed, and a fear of what its existence might mean.", "«فانوس شفا می‌دهد،» سارا زمزمه کرد و در صدایش حیرت بود، و پشت حیرت، چیز دیگری — ترسی از این که چنین قدرتی وجود دارد، و ترسی از اینکه وجودش چه معنایی می‌تواند داشته باشد."),
        StoryParagraph("\"Or maybe it just reminds the body of what it already knows,\" Arin said — and he did not know why he said it, only that the words, once spoken, felt true.", "«یا شاید فقط بدن را یاد چیزی می‌اندازد که خودش می‌دانست،» آرین گفت — و نمی‌دانست چرا این را گفت، تنها این که کلمات، به‌محض گفتن، راستین حس شدند."),
        StoryParagraph("They climbed higher — past the fourth landing, where they found a library of books with no words; past the fifth, where a fountain flowed with ink instead of water; past the sixth, where a door stood without handle or hinge.", "بالاتر رفتند — از پاگرد چهارم گذشتند، جایی که کتابخانه‌ای از کتاب‌های بی‌کلمه یافتند؛ از پنجم، جایی که فواره‌ای به جای آب جوهر جاری بود؛ از ششم، جایی که دری بی‌دستگیره و بی‌لولا ایستاده بود."),
        StoryParagraph("\"How do we open it?\" Sara asked — and the question was not a question, exactly, but a confession that she had run out of ideas.", "«چطور بازش کنیم؟» سارا پرسید — و پرسش، دقیقاً پرسش نبود، بلکه اعترافی بود به این که ایده‌هایش تمام شده."),
        StoryParagraph("Arin held the lantern to the door, and the wood — ancient, unyielding, indifferent — dissolved like fog in sunlight, as though it had been waiting, all along, for nothing more than permission to vanish.", "آرین فانوس را روی در گرفت و چوب — کهن، سرسخت، بی‌اعتنا — مثل مه در برابر نور خورشید حل شد، گویی تمام مدت منتظر چیزی بیش از اجازه برای ناپدید شدن نبود."),
        StoryParagraph("Behind the door was a small chamber with a single window — a window that looked out upon nothing, for there was nothing left to look upon.", "پشت در، اتاقکی کوچک با پنجره‌ای یگانه بود — پنجره‌ای که به هیچ می‌نگریست، چون چیزی برای نگریستن نمانده بود."),
        StoryParagraph("In the center of the chamber, on a bed of white stone, lay an old man — his beard long and silver, his hands folded over his chest, his face peaceful in a way that no living face could ever be.", "وسط اتاقک، روی تختی از سنگ سفید، پیرمردی دراز کشیده بود — ریشش بلند و نقره‌ای، دست‌هایش روی سینه‌اش قلاب‌شده، چهره‌اش آرام به شیوه‌ای که هیچ چهره‌ی زنده‌ای نمی‌توانست باشد."),
        StoryParagraph("Beside him lay a white shield — unmarked, unscratched, as though it had never once been used — and a spear made entirely of light.", "کنارش سپری سفید افتاده بود — بی‌نشان، بی‌خراش، گویی هرگز یک بار هم استفاده نشده — و نیزه‌ای که تماماً از نور ساخته شده بود."),
        StoryParagraph("\"The White Guardian,\" Sara breathed — and the words, spoken aloud, seemed to make the room colder.", "«نگهبان سفید،» سارا نفس‌نفس زد — و کلمات، در حالی که بلند گفته شدند، به نظر می‌رسید اتاق را سردتر کردند."),
        StoryParagraph("Arin knelt beside the sleeping man — slowly, the way one kneels in the presence of something older than oneself, something that demands a reverence one does not fully understand.", "آرین کنار مرد خوابیده زانو زد — آهسته، آن‌گونه که آدم در حضور چیزی کهن‌تر از خودش زانو می‌زند، چیزی که احترامی می‌طلبد که کاملاً نمی‌فهمد."),
        StoryParagraph("He reached out and touched the old man's shoulder — a touch so light that it was almost a question rather than a contact.", "دستش را دراز کرد و شانه‌ی پیرمرد را لمس کرد — لمسی چنان سبک که تقریباً پرسشی بود نه تماسی."),
        StoryParagraph("And the tower shook.", "و برج لرزید."),
        StoryParagraph("Light exploded from the old man's body — not from the lantern, not from the spear, but from within him, as though he had been keeping a small sun trapped beneath his ribs for a thousand years and had only now, at last, permitted it to be seen.", "نور از بدن پیرمرد منفجر شد — نه از فانوس، نه از نیزه، بلکه از درونش، گویی هزار سال خورشیدی کوچک را زیر دنده‌هایش زندانی نگاه داشته بود و تنها حالا، سرانجام، اجازه داده بود دیده شود."),
        StoryParagraph("The light filled the chamber, spilled down the staircase, ran through every crack and crevice of the Silent Tower like water seeking its own level.", "نور اتاقک را پر کرد، از پله‌ها پایین ریخت، از هر ترک و شکاف برج خاموش جاری شد مثل آبی که به دنبال سطح خودش می‌گردد."),
        StoryParagraph("And the old man opened his eyes.", "و پیرمرد چشمانش را باز کرد."),
        StoryParagraph("For one moment — no more — he looked at Arin, and Arin looked at him, and neither of them spoke, because there were no words for what passed between them.", "برای یک لحظه — نه بیشتر — به آرین نگاه کرد و آرین به او نگاه کرد و هیچ‌کدام حرف نزدند، چون کلمه‌ای برای آنچه میانشان گذشت نبود."),
        StoryParagraph("Then the old man closed his eyes again, and the light dimmed, and the tower was silent, and Arin knew, with a certainty he could not explain, that he had just been given something he would spend the rest of his life learning how to carry.", "بعد پیرمرد دوباره چشمانش را بست و نور کم‌رنگ شد و برج ساکت شد و آرین، با یقینی که نمی‌توانست توضیح دهد، دانست که همین تازه چیزی به او داده شده که باقی عمرش را صرف یادگیری حمل کردنش خواهد کرد.")
    )
)
// ─────────── فصل ۵: بیداری نگهبان ───────────
private fun chapter5() = StoryChapter(
    number = 5, title = "The Awakening of the Guardian", titlePersian = "بیداری نگهبان",
    paragraphs = listOf(
        StoryParagraph("When the old man opened his eyes for the second time, they were the color of fresh snow at sunrise — not white, not grey, but something between, something that held within it the memory of warmth without the arrogance of fire.", "وقتی پیرمرد برای بار دوم چشمانش را باز کرد، به رنگ برف تازه در سپیده‌دم بودند — نه سفید، نه خاکستری، بلکه چیزی میان این دو، چیزی که خاطره‌ی گرما را در خود داشت بی‌آنکه گستاخی آتش را داشته باشد."),
        StoryParagraph("\"You finally came,\" he said, and his voice was like wind moving through wheat — soft, vast, and carrying within it the echoes of a thousand harvests.", "«بالاخره آمدی،» گفت و صدایش مثل بادی بود که در گندم می‌گذرد — نرم، پهناور، و طنین هزار برداشت را در خود داشت."),
        StoryParagraph("Arin helped him sit up — slowly, carefully, the way one handles something that has been waiting a very long time and might not yet remember how to be held.", "آرین کمکش کرد بنشیند — آهسته، با احتیاط، آن‌گونه که آدم چیزی را که مدتی بسیار طولانی منتظر بوده و ممکن است هنوز یادش نیامده باشد چطور نگه داشته شود، حمل می‌کند."),
        StoryParagraph("\"My name is Kaveh,\" the old man said. \"I am the last guardian of light. And you, I think, are the boy the lantern has been waiting for.\"", "«نام من کاوه است،» پیرمرد گفت. «من آخرین نگهبان نور هستم. و تو، فکر می‌کنم، پسری هستی که فانوس منتظرش بوده.»"),
        StoryParagraph("Sara stepped forward — and her voice, when she spoke, carried a hope she had clearly been holding for so long that releasing it seemed almost to hurt.", "سارا جلو آمد — و صدایش، وقتی حرف زد، امیدی را حمل می‌کرد که آشکارا چنان طولانی نگه داشته بود که رهایش کردن تقریباً درد داشت."),
        StoryParagraph("\"My father — the Blue Guardian — is he alive?\" she asked.", "«پدرم — نگهبان آبی — زنده است؟» پرسید."),
        StoryParagraph("Kaveh's face softened — and the softening was terrible, because it was the softening of a man who had carried the answer to that question for a very long time, and who had never known how to deliver it without doing harm.", "چهره‌ی کاوه نرم شد — و نرم شدنش هولناک بود، چون نرم شدن مردی بود که پاسخ آن پرسش را مدتی بسیار طولانی حمل کرده بود و هرگز ندانسته بود چگونه آن را بدون آسیب رساندن ادا کند."),
        StoryParagraph("\"Yes,\" he said at last. \"All six are alive. But they are imprisoned in Diozen's fortress, bound not by chains but by their own deepest wounds.\"", "«بله،» سرانجام گفت. «هر شش نفر زنده‌اند. اما در قلعه‌ی دیوژن زندانی‌اند، نه با زنجیر بسته، بلکه با عمیق‌ترین زخم‌های خودشان.»"),
        StoryParagraph("\"Where is the fortress?\" Arin asked, and his own voice, when he heard it, had acquired a quality he did not recognize — something harder than curiosity, quieter than demand.", "«قلعه کجاست؟» آرین پرسید و صدای خودش، وقتی شنیدش، کیفیتی یافته بود که تشخیص نمی‌داد — چیزی سخت‌تر از کنجکاوی، آرام‌تر از تقاضا."),
        StoryParagraph("\"At the edge of the world,\" Kaveh said, \"where the sun once set. Or where, if the world still remembered how, the sun would set now.\"", "«لبه‌ی جهان،» کاوه گفت، «آنجا که خورشید غروب می‌کرد. یا جایی که، اگر جهان هنوز به یاد می‌آورد چگونه، خورشید اکنون غروب می‌کرد.»"),
        StoryParagraph("He reached for the white shield and lifted it with both hands — hands that trembled not with weakness but with the weight of what they had carried for a thousand years.", "دستش را به سوی سپر سفید دراز کرد و آن را با هر دو دست بلند کرد — دستانی که نه از ضعف می‌لرزیدند، بلکه از وزن آنچه هزار سال حمل کرده بودند."),
        StoryParagraph("\"This shield has protected the light since before your city had a name,\" he said. \"Now it is yours, Arin. But know that you carry it not for yourself, but for those who will never see it.\"", "«این سپر از زمانی که شهر تو نامی نداشت از نور محافظت کرده،» گفت. «حالا مال توست، آرین. اما بدان که آن را نه برای خودت حمل می‌کنی، بلکه برای کسانی که هرگز آن را نخواهند دید.»"),
        StoryParagraph("Arin took it — and the weight, when it settled into his hands, was somehow exactly right, as though it had been waiting for precisely these hands and no others.", "آرین آن را گرفت — و وزن، وقتی در دستانش نشست، به‌نحوی دقیقاً درست بود، گویی منتظر همان دست‌ها و نه دیگری بوده بود."),
        StoryParagraph("Then Kaveh reached for the spear of light and placed it in Sara's hands — and Sara, for all her composure, could not keep her fingers from trembling.", "سپس کاوه دستش را به سوی نیزه‌ی نور دراز کرد و آن را در دستان سارا گذاشت — و سارا، با تمام خونسردی‌اش، نتوانست انگشتانش را از لرزیدن باز دارد."),
        StoryParagraph("\"This spear belonged to your father,\" Kaveh said, and his voice, when he said it, was not the voice of a guardian but the voice of an old man returning something that had been entrusted to him far too long ago.", "«این نیزه مال پدرت بود،» کاوه گفت و صدایش، وقتی این را می‌گفت، نه صدای نگهبانی بود بلکه صدای پیرمردی که چیزی را بازمی‌گرداند که بسیار پیش‌تر از این به او سپرده شده بود."),
        StoryParagraph("\"He asked me to give it to you if you ever came. He said you would come. He said you would not know why, but you would come.\"", "«از من خواست اگر آمدی به تو بدهم. گفت خواهی آمد. گفت نمی‌دانی چرا، اما خواهی آمد.»"),
        StoryParagraph("Sara's eyes filled with tears — but she did not let them fall; and in that refusal, Arin saw something that made him understand, for the first time, the difference between a girl who had suffered and a woman who had learned how to suffer well.", "چشمان سارا پر از اشک شد — اما نگذاشت بچکند؛ و در آن امتناع، آرین چیزی دید که برای نخستین بار، تفاوت میان دختری که رنج کشیده بود و زنی که آموخته بود خوب رنج بکشد را فهمید."),
        StoryParagraph("\"How do we free the guardians?\" she asked, and her voice, though thick, was steady.", "«چطور نگهبان‌ها را آزاد کنیم؟» پرسید و صدایش، هرچند گرفته، ثابت بود."),
        StoryParagraph("\"Each guardian is imprisoned by a different darkness,\" Kaveh said — and he spoke now with the care of a man reciting something he had rehearsed in his sleep for a thousand years.", "«هر نگهبان با تاریکی متفاوتی زندانی شده،» کاوه گفت — و حالا با دقتی حرف می‌زد که مردی داشت چیزی را می‌خواند که هزار سال در خواب تمرینش کرده بود."),
        StoryParagraph("\"The Red Guardian is chained by fear — but not by any fear of death or pain. By the fear that his courage was never real; that all his bravery was a mask; that, beneath the hero's armor, there has always been only a small and frightened child.\"", "«نگهبان سرخ با ترس زنجیر شده — اما نه از هر ترس از مرگ یا درد. از ترس اینکه شجاعتش هرگز راستین نبوده؛ که تمام دلاوری‌اش ماسکی بوده؛ که زیر زره قهرمان، همیشه فقط بچه‌ای کوچک و ترسیده بوده است.»"),
        StoryParagraph("\"The Orange Guardian is trapped in cold — the cold of a heart that has loved too much and been abandoned too often. Only warmth can free her — but warmth offered without condition, without expectation, without the small cruelties we mistake for honesty.\"", "«نگهبان نارنجی در سرما گرفتار شده — سرمای قلبی که بیش از حد عشق ورزیده و بیش از حد رها شده. فقط گرما می‌تواند آزادش کند — اما گرمایی که بی‌شرط عرضه شود، بی‌انتظار، و بدون قساوت‌های کوچکی که با صداقت اشتباه می‌گیریم.»"),
        StoryParagraph("\"The Yellow Guardian is blinded by lies — not the lies of others, but his own. The lies he has told himself for so long that they have become the very ground beneath his feet. Only hope can free him — hope that does not require proof, hope that precedes evidence.\"", "«نگهبان زرد با دروغ کور شده — نه دروغ‌های دیگران، بلکه دروغ‌های خودش. دروغ‌هایی که آن‌قدر طولانی به خودش گفته که به همان زمین زیر پایش بدل شده‌اند. فقط امید می‌تواند آزادش کند — امیدی که اثبات نمی‌طلبد، امیدی که پیش از شواهد می‌آید.»"),
        StoryParagraph("\"The Green Guardian is dying of a wound — a wound she received while healing another, a wound no one saw, a wound she never permitted herself to name. Only healing can free her — and the hardest healing is the healing we must offer ourselves.\"", "«نگهبان سبز از زخمی می‌میرد — زخمی که وقتی دیگری را شفا می‌داد دریافت، زخمی که هیچ‌کس ندید، زخمی که هرگز به خود اجازه نداد نامش را ببرد. فقط شفا می‌تواند آزادش کند — و سخت‌ترین شفا، شفایی است که باید به خودمان عرضه کنیم.»"),
        StoryParagraph("\"The Blue Guardian is silenced by a truth he cannot speak — and that truth, Sara, is a truth that belongs to you as much as to him. Only you can free him. Only the daughter he failed to protect can restore to him the voice he lost trying to protect her.\"", "«نگهبان آبی با حقیقتی که نمی‌تواند بگوید سکوت شده — و آن حقیقت، سارا، حقیقتی است که به همان اندازه که به او تعلق دارد، به تو هم تعلق دارد. فقط تو می‌توانی آزادش کنی. تنها دختری که در محافظتش ناکام ماند، می‌تواند صدایی را که او در تلاش برای محافظت از او از دست داد، به او بازگرداند.»"),
        StoryParagraph("\"The Violet Guardian is lost in a dream — a dream so beautiful that she no longer wishes to wake. Only waking can free her — and waking, as you will learn, is often the crueler gift.\"", "«نگهبان بنفش در رؤیایی گم شده — رؤیایی چنان زیبا که دیگر نمی‌خواهد بیدار شود. فقط بیداری می‌تواند آزادش کند — و بیداری، آن‌طور که خواهید آموخت، اغلب هدیه‌ی بی‌رحم‌تری است.»"),
        StoryParagraph("\"And Diozen himself can only be defeated by a light that comes from within — not from a lantern, not from a spear, not from any relic or weapon. From within. From the place inside you that has never been dark, no matter how dark everything else has been.\"", "«و خود دیوژن فقط با نوری که از درون می‌آید می‌تواند شکست بخورد — نه از فانوس، نه از نیزه، نه از هیچ یادگاری یا سلاحی. از درون. از جایی درون تو که هرگز تاریک نبوده، هر چقدر هم که همه چیز دیگری تاریک بوده باشد.»"),
        StoryParagraph("Arin looked down at the lantern in his hand — at the flame that had burned so steadily, so stubbornly, and that now seemed, to his eyes, somehow smaller than before.", "آرین به فانوس در دستش نگاه کرد — به شعله‌ای که آن‌قدر ثابت، آن‌قدر سرسخت سوخته بود، و حالا به چشمانش، به‌نحوی کوچک‌تر از پیش به نظر می‌رسید."),
        StoryParagraph("\"But my lantern is almost out,\" he said — and the words came out not as a complaint but as a confession, the way one admits to a doctor the symptom one has been hiding for months.", "«اما فانوس من تقریباً خاموش است،» گفت — و کلمات نه به‌عنوان شکایت بیرون آمدند بلکه به‌عنوان اعتراف، همان‌طور که آدم به پزشک نشانه‌ای را که ماه‌ها پنهان کرده اعتراف می‌کند."),
        StoryParagraph("\"That is because the lantern was never the true light,\" Kaveh said — gently, but without softening the fact. \"It was only a reminder. A thread. A question that the world has been asking you, whether or not you knew it.\"", "«چون فانوس هرگز نور راستین نبود،» کاوه گفت — با مهربانی، اما بی‌آنکه واقعیت را نرم کند. «فقط یادآوری بود. رشته‌ای. پرسشی که جهان از تو می‌پرسیده، خواه می‌دانستی خواه نه.»"),
        StoryParagraph("\"A reminder of what?\"", "«یادآور چه؟»"),
        StoryParagraph("\"Of what you already are,\" Kaveh said. \"Of what you have always been. Of what, if you are brave enough, you will one day consent to become.\"", "«یادآور اینکه تو از قبل چه هستی،» کاوه گفت. «یادآور اینکه همیشه چه بوده‌ای. یادآور اینکه، اگر به‌قدر کافی شجاع باشی، روزی رضایت خواهی داد که چه شوی.»"),
        StoryParagraph("Kaveh stood — and despite his age, despite the thousand years that seemed to hang upon his shoulders like a cloak, he stood tall.", "کاوه بلند شد — و با وجود سنش، با وجود هزار سالی که به نظر می‌رسید مثل ردایی بر شانه‌هایش آویزان بود، بلند ایستاد."),
        StoryParagraph("\"I will fight beside you,\" he said. \"But I cannot lead. That is your task now, Arin. The lantern chose you, and the lantern has never yet chosen wrongly.\"", "«کنارت می‌جنگم،» گفت. «اما نمی‌توانم رهبری کنم. این وظیفه‌ی توست، آرین. فانوس تو را انتخاب کرد، و فانوس هرگز اشتباه انتخاب نکرده است.»"),
        StoryParagraph("Arin wanted to protest — wanted to say that he was too young, too weak, too afraid, that he did not know what he was doing and had never known, that the world was asking of him something he did not possess.", "آرین می‌خواست اعتراض کند — می‌خواست بگوید زیادی جوان است، زیادی ضعیف، زیادی ترسیده، که نمی‌داند چه می‌کند و هرگز نمی‌دانسته، که جهان چیزی از او می‌طلبد که ندارد."),
        StoryParagraph("But the words would not come — and in their place, there came something else: a small, quiet, stubborn certainty that perhaps the world was not asking him to possess it, but only to seek it.", "اما کلمات نیامدند — و به‌جایشان چیز دیگری آمد: یقینی کوچک، آرام، سرسخت که شاید جهان از او نمی‌خواهد داشته باشد، بلکه تنها می‌خواهد بجوید."),
        StoryParagraph("He looked at Sara, and Sara — who had learned long ago that some moments require no words — simply nodded.", "به سارا نگاه کرد و سارا — که مدتها پیش آموخته بود برخی لحظات کلمه نمی‌خواهند — فقط سر تکان داد."),
        StoryParagraph("He looked at the lantern, and the lantern burned steady and true, as though it had been waiting for precisely this moment and had never once doubted it would arrive.", "به فانوس نگاه کرد و فانوس ثابت و راستین سوخت، گویی دقیقاً منتظر همین لحظه بود و هرگز یک بار هم شک نکرده بود که خواهد رسید."),
        StoryParagraph("He looked at the shield in his hands, and the weight of it settled against his ribs like a second heartbeat — softer than his own, older than his own, and somehow more patient.", "به سپر در دستانش نگاه کرد و وزنش مثل ضربان دومی در دنده‌هایش نشست — نرم‌تر از ضربان خودش، کهن‌تر از ضربان خودش، و به‌نحوی صبورتر."),
        StoryParagraph("\"Then we leave at dawn,\" Arin said — and the words, once spoken, felt not like a decision but like a recognition.", "«پس سپیده‌دم راه می‌افتیم،» آرین گفت — و کلمات، به‌محض گفتن، نه تصمیمی حس شدند بلکه بازشناسی‌ای."),
        StoryParagraph("\"There is no dawn,\" Kaveh said — and then, seeing the flicker of something in Arin's eyes, he added, more softly: \"Not yet. But there will be.\"", "«سپیده‌دەمی نیست،» کاوه گفت — و بعد، چون لرزشی در چشمان آرین دید، آرام‌تر اضافه کرد: «هنوز نه. اما خواهد بود.»"),
        StoryParagraph("They slept in the tower that night — all three of them, side by side on the cold stone floor, the lantern between them like a small and patient argument against despair.", "آن شب در برج خوابیدند — هر سه، کنار هم روی کف سرد سنگی، فانوس میانشان مثل استدلالی کوچک و صبور علیه ناامیدی."),
        StoryParagraph("And for the first time in days — for the first time, perhaps, in years — Arin dreamed of light.", "و برای نخستین بار در چند روز — برای نخستین بار، شاید، در چند سال — آرین خواب نور دید."),
        StoryParagraph("He dreamed of a city where the sun rose every morning, and where no one ever feared the dark — a city that looked, in the way of dreams, both like Arkadia and like nothing he had ever seen.", "خواب شهری را دید که هر صبح خورشید در آن طلوع می‌کرد و هیچ‌کس هرگز از تاریکی نمی‌ترسید — شهری که، به شیوه‌ی رؤیاها، هم شبیه آرکادیا بود و هم شبیه چیزی که هرگز ندیده بود."),
        StoryParagraph("He dreamed of his grandfather — who smiled, and said nothing, because there was nothing left to say, and who then, slowly, began to fade.", "خواب پدربزرگش را دید — که لبخند زد و چیزی نگفت، چون چیزی برای گفتن نمانده بود، و بعد، آهسته، شروع به محو شدن کرد."),
        StoryParagraph("When Arin woke, the lantern was brighter than it had ever been — and in his chest, something new was burning, something that had been there all along but that he had, until this moment, lacked the vocabulary to name.", "وقتی آرین بیدار شد، فانوس روشن‌تر از همیشه بود — و در سینه‌اش، چیزی تازه می‌سوخت، چیزی که تمام مدت آنجا بود اما تا این لحظه، واژگانی برای نامیدنش نداشت."),
        StoryParagraph("And he knew — with a certainty that surprised him, and yet that seemed, somehow, always to have been his — that he would never again be afraid of the dark.", "و دانست — با یقینی که خودش را هم متعجب کرد، و با این حال که به‌نحوی، همیشه مال خودش به نظر می‌رسید — که دیگر هرگز از تاریکی نخواهد ترسید.")
    )
)
// ─────────── فصل ۶: نبرد نهایی ───────────
private fun chapter6() = StoryChapter(
    number = 6, title = "The Final Battle", titlePersian = "نبرد نهایی",
    paragraphs = listOf(
        StoryParagraph("The journey to Diozen's fortress took three days — three days without sun, without stars, without any light but the lantern's small and stubborn refusal to surrender.", "سفر به قلعه‌ی دیوژن سه روز طول کشید — سه روز بدون خورشید، بدون ستاره، بدون هیچ نوری جز امتناع کوچک و سرسخت فانوس از تسلیم شدن."),
        StoryParagraph("The road was paved with black glass — not dark stone, not shadowed earth, but glass, smooth and cold and utterly without reflection, as though the world had been polished away until only absence remained.", "راه با شیشه‌ی سیاه فرش شده بود — نه سنگ تیره، نه خاک سایه‌گرفته، بلکه شیشه، صاف و سرد و کاملاً بی‌بازتاب، گویی جهان آن‌قدر صیقل داده شده بود تا تنها غیابت باقی بماند."),
        StoryParagraph("With every mile, the sky grew darker — until at last it was not a sky at all, but a ceiling, low and heavy and pressing down, as though the world had been roofed over by something that did not wish to be looked at.", "با هر مایل، آسمان تاریک‌تر می‌شد — تا جایی که دیگر آسمان نبود، بلکه سقفی بود، کوتاه و سنگین و فشارآور، گویی جهان توسط چیزی که نمی‌خواست به آن نگاه شود، سرپوش شده بود."),
        StoryParagraph("Kaveh walked with a staff of pale wood; Sara walked with her father's spear; Arin walked with the lantern in one hand and the white shield in the other — and none of them spoke, because speech, here, felt like a language the land had never learned.", "کاوه با عصایی از چوب رنگ‌پریده راه می‌رفت؛ سارا با نیزه‌ی پدرش؛ آرین با فانوس در یک دست و سپر سفید در دست دیگر — و هیچ‌کدام حرف نزدند، چون گفتار، اینجا، زبانی به نظر می‌رسید که این سرزمین هرگز نیاموخته بود."),
        StoryParagraph("At last, they saw the fortress — and the fortress was not a building, though it had walls and towers and gates.", "بالاخره قلعه را دیدند — و قلعه ساختمان نبود، هرچند دیوار و برج و دروازه داشت."),
        StoryParagraph("It was a wound — a wound in the world itself, an absence shaped like a structure, a place where the world had been torn and had never quite healed.", "زخمی بود — زخمی در خود جهان، غیابتی به شکل ساختار، جایی که جهان دریده شده بود و هرگز کاملاً التیام نیافته بود."),
        StoryParagraph("Its towers pierced the darkness like broken teeth, uneven and jagged and patient; its gates stood open, as though Diozen had known they were coming and had decided that barring their way would have been, somehow, beneath him.", "برج‌هایش تاریکی را مثل دندان‌های شکسته سوراخ کرده بودند، ناهموار و دندانه‌دار و صبور؛ دروازه‌هایش باز ایستاده بودند، گویی دیوژن می‌دانست در راه‌اند و تصمیم گرفته بود که سد کردن راهشان، به‌نحوی، زیر شأنش باشد."),
        StoryParagraph("\"He wants us here,\" Sara said, and her voice was quiet, and her eyes were fixed on the gate the way one fixes one's eyes on the edge of a cliff.", "«می‌خواهد ما اینجا باشیم،» سارا گفت و صدایش آرام بود و چشمانش به دروازه خیره بود، همان‌طور که آدم به لبه‌ی پرتگاه خیره می‌شود."),
        StoryParagraph("\"Then let us not disappoint him,\" Kaveh said — and there was iron in his voice, iron that had been forged long ago and had never once been permitted to rust.", "«پس ناامیدش نکنیم،» کاوه گفت — و آهنی در صدایش بود، آهنی که مدتها پیش آهنگری شده بود و هرگز یک بار هم اجازه نداده بودند زنگ بزند."),
        StoryParagraph("They walked through the gate.", "از دروازه گذشتند."),
        StoryParagraph("The great hall beyond was vast — vaster than the fortress had any right to be, as though space itself had been stretched to accommodate something that did not belong to space.", "تالار بزرگ آن‌سو پهناور بود — پهناورتر از آنچه قلعه حقی داشت باشد، گویی خود فضا کشیده شده بود تا چیزی را که به فضا تعلق نداشت، در خود جای دهد."),
        StoryParagraph("From the ceiling hung six cages — not iron cages, not wooden, but cages of shadow itself, wrought from the same absence that had swallowed the sky.", "از سقف شش قفس آویزان بود — نه قفس آهنی، نه چوبی، بلکه قفس‌هایی از خود سایه، آهنگری‌شده از همان غیابتی که آسمان را بلعیده بود."),
        StoryParagraph("Inside each cage was a guardian — pale, still, and barely breathing, as though life itself had been slowed within them to the merest whisper of its usual pulse.", "داخل هر قفس نگهبانی بود — رنگ‌پریده، بی‌حرکت، و به‌سختی نفس‌کشنده، گویی خود زندگی درونشان تا نجوا‌ترین ضربان معمولش آهسته شده بود."),
        StoryParagraph("The Red Guardian, whose face was streaked with tears he had never permitted anyone to see; the Orange Guardian, whose hands had folded themselves around her own chest as though protecting something no longer there; the Yellow Guardian, whose eyes stared at nothing and saw less.", "نگهبان سرخ، که چهره‌اش با اشکی آغشته بود که هرگز اجازه نداده بود کسی ببیند؛ نگهبان نارنجی، که دست‌هایش دور سینه‌ی خودش قلاب شده بودند گویی از چیزی که دیگر آنجا نبود محافظت می‌کردند؛ نگهبان زرد، که چشمانش به هیچ خیره بود و کمتر می‌دید."),
        StoryParagraph("The Green Guardian, whose wound was invisible but whose pain was written in the lines of her face; the Blue Guardian — Sara's father — whose mouth was open but from which no sound would ever come; the Violet Guardian, whose eyes were closed and whose lips curved in a smile that belonged entirely to some other world.", "نگهبان سبز، که زخمش نامرئی بود اما دردش در خطوط چهره‌اش نوشته شده بود؛ نگهبان آبی — پدر سارا — که دهانش باز بود اما از آن هرگز صدایی نمی‌آمد؛ نگهبان بنفش، که چشمانش بسته بود و لب‌هایش در لبخندی خمیده بود که کاملاً به جهان دیگری تعلق داشت."),
        StoryParagraph("And on a throne of shadows — a throne that was not built so much as accumulated, layer upon layer of everything the world had ever refused to look at — sat Diozen.", "و روی تختی از سایه‌ها — تختی که نه ساخته شده بود بلکه انباشته شده بود، لایه‌روی‌لایه از هر چیزی که جهان هرگز از نگاه کردن به آن سر باز زده بود — دیوژن نشسته بود."),
        StoryParagraph("He was tall and thin, and his face was beautiful in the way that a knife is beautiful — in the way that anything is beautiful whose sole purpose is to be used.", "قدبلند و لاغر بود و چهره‌اش زیبا بود، آن‌طور که چاقو زیباست — آن‌طور که هر چیزی زیباست که تنها هدفش استفاده شدن است."),
        StoryParagraph("\"So,\" he said, and his voice was soft and intimate and utterly without warmth — the voice of someone who had learned long ago that cruelty is most effective when it is dressed as kindness.", "«خب،» گفت و صدایش نرم و صمیمی و کاملاً بی‌گرما بود — صدای کسی که مدتها پیش آموخته بود بی‌رحمی وقتی به‌عنوان مهربانی پوشیده شود، مؤثرتر است."),
        StoryParagraph("\"The last guardian brings me two children. How generous of him. How very, very generous.\"", "«آخرین نگهبان برایم دو بچه آورده. چقدر سخاوتمندانه از او. چه بسیار، بسیار سخاوتمندانه.»"),
        StoryParagraph("\"We are not children,\" Arin said — and his voice, when he heard it, surprised him; it was steadier than he felt, and harder than he had known he could be.", "«ما بچه نیستیم،» آرین گفت — و صدایش، وقتی شنیدش، متعجبش کرد؛ ثابت‌تر از آنچه حس می‌کرد بود و سخت‌تر از آنچه می‌دانست می‌تواند باشد."),
        StoryParagraph("\"You are to me,\" Diozen replied — and he smiled, and the smile was worse than any threat could have been. \"I have lived for ten thousand years. You are mayflies — brief, bright, and utterly without consequence.\"", "«برای من هستید،» دیوژن پاسخ داد — و لبخند زد و لبخندش از هر تهدیدی بدتر بود. «ده هزار سال زندگی کرده‌ام. شما مگس‌های یک‌روزه‌اید — کوتاه، درخشان، و کاملاً بی‌پیامد.»"),
        StoryParagraph("He raised his hand — casually, almost lazily — and the shadows rose.", "دستش را بالا برد — عادی، تقریباً با تنبلی — و سایه‌ها بلند شدند."),
        StoryParagraph("Kaveh charged first, his staff blazing with light — and Sara followed, her father's spear singing in her hands like something that had been waiting far too long to be used.", "کاوه اول یورش برد، عصایش با نور می‌درخشید — و سارا دنبالش، نیزه‌ی پدرش در دستانش آواز می‌خواند، مثل چیزی که بسیار طولانی منتظر استفاده شدن بوده بود."),
        StoryParagraph("Arin held the lantern high — and its light, though small, cut through the shadows as though they were not there at all, as though the darkness had only ever been a rumor that the lantern now refuted.", "آرین فانوس را بالا نگه داشت — و نورش، هرچند کوچک، سایه‌ها را طوری می‌برید که گویی اصلاً وجود ندارند، گویی تاریکی فقط شایعه‌ای بوده که فانوس اکنون ردش می‌کرد."),
        StoryParagraph("The shadows met them like a tide — wave after wave, each darker than the last, each hungrier than the last — and the three of them fought, not as heroes in a legend but as people who had discovered that courage was not the absence of fear but the refusal to let fear make one's decisions.", "سایه‌ها مثل جزر و مد به آن‌ها رسیدند — موج پس از موج، هر یک تاریک‌تر از پیش، هر یک گرسنه‌تر از پیش — و آن سه جنگیدند، نه به‌عنوان قهرمانان افسانه، بلکه به‌عنوان کسانی که کشف کرده بودند شجاعت نه غیبت ترس است بلکه امتناع از این که ترس تصمیم‌های آدم را بگیرد."),
        StoryParagraph("Kaveh fought with the fury of a man who had slept for a thousand years and had woken to find the world he had sworn to protect on the edge of ruin.", "کاوه با خشم مردی جنگید که هزار سال خوابیده بود و بیدار شده بود تا جهانی را که قسم خورده بود محافظتش کند، در لبه‌ی تباهی ببیند."),
        StoryParagraph("Sara fought with the precision of someone who had trained, alone, for years, in cold rooms and empty courtyards, always with the quiet certainty that this day would come.", "سارا با دقت کسی جنگید که سال‌ها، تنها، در اتاق‌های سرد و حیاط‌های خالی تمرین کرده بود، همیشه با یقین خاموشی که این روز خواهد آمد."),
        StoryParagraph("Arin fought with the lantern — and with something else, something that had been growing in him since the night he had first opened his grandfather's letter; something that did not yet have a name but that had begun, at last, to burn.", "آرین با فانوس جنگید — و با چیز دیگری، چیزی که از شبی که نخستین بار نامه‌ی پدربزرگش را باز کرده بود در او رشد می‌کرد؛ چیزی که هنوز نامی نداشت اما بالاخره، شروع به سوختن کرده بود."),
        StoryParagraph("The first cage cracked — not shattered, but cracked, as though something inside had pushed against it for the first time in years. The Red Guardian fell to the floor, gasping.", "قفس اول ترک خورد — نه خرد شد، بلکه ترک خورد، گویی چیزی درونش برای نخستین بار در سال‌ها به آن فشار آورده بود. نگهبان سرخ نفس‌نفس‌زنان روی زمین افتاد."),
        StoryParagraph("The second cage cracked. The Orange Guardian opened her eyes — and in those eyes, Arin saw a warmth that had been buried so long it had almost forgotten the shape of the world.", "قفس دوم ترک خورد. نگهبان نارنجی چشمانش را باز کرد — و در آن چشمان، آرین گرمایی دید که آن‌قدر طولانی مدفون شده بود که تقریباً شکل جهان را فراموش کرده بود."),
        StoryParagraph("The third, the fourth, the fifth — each cage shattered, each guardian released, each body collapsing to the floor like a breath that had been held too long.", "سوم، چهارم، پنجم — هر قفس خرد شد، هر نگهبان آزاد شد، هر بدن مثل نفسی که بسیار طولانی نگه داشته شده بود روی زمین فرو افتاد."),
        StoryParagraph("The sixth cage held Sara's father — and it was Sara herself who cut him down, with her own hands, with her father's own spear, and when he fell into her arms, he looked at her with eyes that had not been permitted to weep for years.", "قفس ششم پدر سارا را در خود داشت — و خودِ سارا بود که پایینش آورد، با دستان خودش، با نیزه‌ی خودِ پدرش، و وقتی در آغوشش افتاد، با چشمانی نگاهش کرد که سال‌ها اجازه‌ی گریستن نداشته بودند."),
        StoryParagraph("\"You came,\" he whispered — and the words, coming from a throat that had been silenced for so long, sounded less like speech than like the first breath of a man who had been drowning.", "«آمدی،» زمزمه کرد — و کلمات، از گلویی که این‌قدر طولانی سکوت کرده بود، کمتر شبیه گفتار بودند و بیشتر شبیه نخستین نفس مردی که در حال غرق شدن بوده."),
        StoryParagraph("\"I always would,\" she said — and then, because there was nothing else to say, and because there would be time enough for words later, she held him, and he wept.", "«همیشه می‌آمدم،» گفت — و بعد، چون چیز دیگری برای گفتن نبود، و چون برای کلمات بعداً وقت کافی بود، او را در آغوش گرفت و او گریست."),
        StoryParagraph("Now only Diozen remained.", "حالا فقط دیوژن مانده بود."),
        StoryParagraph("He had not moved from his throne; he had not needed to. He watched the freeing of his prisoners with the calm of a man who had never once doubted the outcome of the battle, because to him, there had never been a battle at all — only a delay.", "از تختش تکان نخورده بود؛ نیازی نداشت. آزاد شدن زندانیانش را با آرامش مردی تماشا کرد که هرگز یک بار هم در نتیجه‌ی نبرد شک نکرده بود، چون برای او، هرگز نبردی نبوده — فقط تأخیری."),
        StoryParagraph("\"You think you have won?\" he said, and his laugh was like a mountain falling — vast, patient, and indifferent to whatever happened to be beneath it. \"You have only made me stronger. Every light you free, every guardian you wake — they feed me. They always have.\"", "«فکر می‌کنی برده‌ای؟» گفت و خنده‌اش مثل فرو ریختن کوهی بود — پهناور، صبور، و بی‌اعتنا به هر چه اتفاقاً زیرش باشد. «فقط قوی‌ترم کردی. هر نوری که آزاد می‌کنی، هر نگهبانی که بیدار می‌کنی — مرا تغذیه می‌کنند. همیشه کرده‌اند.»"),
        StoryParagraph("He raised his hand again — and this time, the darkness did not come as shadows; it came as a single point, condensed, absolute, the shape of a void that had been waiting to be aimed.", "دوباره دستش را بالا برد — و این بار، تاریکی به‌عنوان سایه نیامد؛ به‌عنوان نقطه‌ای یگانه آمد، فشرده، مطلق، شکلی از خلأ که منتظر نشانه‌گیری بوده است."),
        StoryParagraph("It struck Arin in the chest.", "به سینه‌ی آرین خورد."),
        StoryParagraph("The lantern shattered — not cracked, not dimmed, but shattered, its brass frame folding inward, its cracked glass breaking into a hundred pieces, its flame extinguished as though it had never existed.", "فانوس خرد شد — نه ترک خورد، نه کم‌نور شد، بلکه خرد شد، قاب برنجی‌اش به داخل تا شد، شیشه‌ی ترک‌خورده‌اش به صد تکه شکست، شعله‌اش خاموش شد گویی هرگز وجود نداشته."),
        StoryParagraph("For a moment — no more — Arin felt nothing but cold, a cold so absolute that it seemed less like a temperature than a verdict.", "برای لحظه‌ای — نه بیشتر — آرین چیزی جز سرما حس نکرد، سرمایی چنان مطلق که کمتر شبیه دما بود و بیشتر شبیه حکم."),
        StoryParagraph("The world went dark.", "جهان تاریک شد."),
        StoryParagraph("But then — in the darkness, in the cold, in the silence that followed the shattering of the only light he had ever known — Arin remembered.", "اما بعد — در تاریکی، در سرما، در سکوتی که پس از خرد شدن تنها نوری که هرگز شناخته بود آمد — آرین به یاد آورد.")
    )
)
    // ─────────── فصل ۷: طلوع دوباره ───────────
    private fun chapter7() = StoryChapter(
        number = 7, title = "Dawn Again", titlePersian = "طلوع دوباره",
        paragraphs = listOf(
            StoryParagraph("The cold did not last — or rather, the cold lasted exactly as long as it needed to, and then it receded, the way a wave recedes from a shore it has finished testing.", "سرما دوام نیاورد — یا بهتر بگویم، سرما دقیقاً به همان اندازه که لازم بود دوام آورد و بعد عقب نشست، همان‌طور که موجی از ساحلی که آزمودنش را تمام کرده عقب می‌نشیند."),
            StoryParagraph("Because in that moment — in that absolute, unlit, unspeakable moment — Arin remembered every person who had ever lit a candle for someone else.", "چون در آن لحظه — در آن لحظه‌ی مطلق، بی‌نور، ناگفتنی — آرین هر کسی را به یاد آورد که هرگز برای کس دیگری شمعی روشن کرده بود."),
            StoryParagraph("He remembered his grandfather, who had left him a lantern instead of a fortune — because he had understood, long before Arin could, that light was the only inheritance worth passing down.", "پدربزرگش را به یاد آورد، که به جای ثروت فانوسی برایش گذاشته بود — چون مدتها پیش از آنکه آرین بتواند بفهمد، فهمیده بود که نور تنها میراثی است که ارزش دست‌به‌دست شدن دارد."),
            StoryParagraph("He remembered Maryam, who had told him to go — not because she was unafraid, but because she had decided, long ago, that some fears were worth dying for.", "مریم را به یاد آورد، که به او گفته بود برو — نه چون نمی‌ترسید، بلکه چون مدتها پیش تصمیم گرفته بود که بعضی ترس‌ها ارزش مردن دارند."),
            StoryParagraph("He remembered Sara, who had trusted him when he had not yet learned to trust himself — who had held out her hand on a frozen mountain and had waited, patiently, for him to take it.", "سارا را به یاد آورد، که وقتی او هنوز یاد نگرفته بود به خودش اعتماد کند، به او اعتماد کرد — که دستش را روی کوهی یخ‌زده دراز کرده بود و صبورانه منتظر مانده بود که او بگیردش."),
            StoryParagraph("He remembered Kaveh, who had slept for a thousand years and had still, upon waking, believed in the light — a belief so old and so tested that it had become, in some way, indistinguishable from the light itself.", "کاوه را به یاد آورد، که هزار سال خوابیده بود و با این حال، پس از بیدار شدن، هنوز به نور باور داشت — باوری چنان کهن و چنان آزموده که به‌نحوی، از خودِ نور قابل تفکیک نبود."),
            StoryParagraph("He remembered the woman in the street who had prayed to a god who did not answer — and he understood, at last, that perhaps the answer had never been meant to come from above, but from within.", "زنی را در خیابان به یاد آورد که برای خدایی که جواب نمی‌داد دعا می‌کرد — و بالاخره فهمید که شاید پاسخ هرگز قرار نبوده از بالا بیاید، بلکه از درون."),
            StoryParagraph("He remembered every stranger who had ever offered him bread, or water, or a place by a fire, when he had nothing to offer in return.", "هر غریبه‌ای را به یاد آورد که هرگز برایش نان، یا آب، یا جایی کنار آتش عرضه کرده بود، وقتی او چیزی برای عرضه در عوض نداشت."),
            StoryParagraph("He remembered every hand that had ever held his, every voice that had ever said his name, every glance that had ever acknowledged that he existed and mattered.", "هر دستی را به یاد آورد که هرگز دستش را گرفته بود، هر صدایی که هرگز نامش را گفته بود، هر نگاهی که هرگز اقرار کرده بود او هست و اهمیت دارد."),
            StoryParagraph("And in that remembering — in that vast and terrible and beautiful remembering — something broke open inside him.", "و در آن به‌یاد آوردن — در آن به‌یاد آوردن پهناور و هولناک و زیبا — چیزی در درونش شکافت و باز شد."),
            StoryParagraph("It was not a physical breaking; it was not a wound; it was the opening of a door that had always been there, that he had spent his entire life walking past without noticing.", "شکافی فیزیکی نبود؛ زخم نبود؛ باز شدن دری بود که همیشه آنجا بود، دری که تمام عمرش بی‌توجه از کنارش گذشته بود."),
            StoryParagraph("And through that door, at long last, came the light.", "و از آن در، بالاخره، نور آمد."),
            StoryParagraph("It did not come from the lantern — the lantern was gone, shattered on the floor of the fortress — but from a place that no shattering could reach.", "از فانوس نیامد — فانوس رفته بود، خرد شده روی کف قلعه — بلکه از جایی آمد که هیچ خرد شدنی نمی‌توانست برسد."),
            StoryParagraph("It did not come from the spear of light, nor from the white shield, nor from any weapon or relic or artifact — it came from him.", "از نیزه‌ی نور نیامد، نه از سپر سفید، نه از هیچ سلاح یا یادگاری یا مصنوعی — از خودش آمد."),
            StoryParagraph("From the place inside him that had never been dark, no matter how dark everything else had been.", "از جایی درونش که هرگز تاریک نبوده، هر چقدر هم که همه چیز دیگری تاریک بوده باشد."),
            StoryParagraph("The light poured out of his chest — not in streams, not in beams, but in a single, decisive wave, the way dawn breaks over a horizon it has never once, in all the ages of the world, failed to reach.", "نور از سینه‌اش بیرون ریخت — نه در جریان‌ها، نه در پرتوها، بلکه در موجی یگانه و قاطع، همان‌طور که سپیده‌دم بر افقی می‌شکند که هرگز، در تمام دوران‌های جهان، رسیدن به آن را ناکام نگذارده است."),
            StoryParagraph("Diozen screamed.", "دیوژن جیغ کشید."),
            StoryParagraph("It was not a scream of pain, exactly — for he could not feel pain, having long ago surrendered the capacity — but a scream of recognition, the scream of a thing that had spent ten thousand years telling itself a lie and had, at last, been forced to look upon the truth.", "دقیقاً جیغ درد نبود — چون نمی‌توانست درد حس کند، مدتها پیش ظرفیتش را تسلیم کرده بود — بلکه جیغ شناخت بود، جیغ چیزی که ده هزار سال داشت به خودش دروغ می‌گفت و بالاخره، مجبور شده بود به حقیقت نگاه کند."),
            StoryParagraph("\"No!\" he cried. \"You cannot — you are nothing! You are a boy, a child, a mayfly!\"", "«نه!» فریاد زد. «نمی‌توانی — تو هیچی هستی! تو پسری، بچه‌ای، مگسی یک‌روزه!»"),
            StoryParagraph("\"I am not nothing,\" Arin said — and his voice, when he heard it, was no longer the voice of a boy, nor of a man, nor of anything that any language had a word for.", "«من هیچی نیستم،» آرین گفت — و صدایش، وقتی شنیدش، دیگر نه صدای پسری بود، نه مردی، نه چیزی که هر زبانی واژه‌ای برایش داشته باشد."),
            StoryParagraph("\"I am the one who remembers. And as long as there is one person left in this world who remembers love, you will never — never — be able to win.\"", "«من کسی هستم که به یاد می‌آورد. و تا وقتی یک نفر در این جهان بماند که عشق را به یاد بیاورد، تو هرگز — هرگز — نمی‌توانی ببری.»"),
            StoryParagraph("The light grew — and it did not grow gently.", "نور رشد کرد — و به‌ملایمت رشد نکرد."),
            StoryParagraph("It grew the way a flood grows, the way a fire grows, the way truth grows when it has been denied too long and can no longer be held back.", "همان‌طور رشد کرد که سیل رشد می‌کند، همان‌طور که آتش رشد می‌کند، همان‌طور که حقیقت رشد می‌کند وقتی آن‌قدر طولانی انکار شده که دیگر نمی‌تواند نگه داشته شود."),
            StoryParagraph("It touched the guardians, and they rose — not because they had been healed, but because the light reminded them of who they had been before the wound, before the doubt, before the darkness.", "به نگهبان‌ها خورد و برخاستند — نه چون شفا یافته بودند، بلکه چون نور به یادشان آورد پیش از زخم، پیش از شک، پیش از تاریکی چه بوده‌اند."),
            StoryParagraph("It touched the walls, and the walls crumbled — not because they had been broken, but because they had never been more than a promise that the light had now declined to keep.", "به دیوارها خورد و فرو ریختند — نه چون شکسته شده بودند، بلکه چون چیزی بیش از وعده‌ای که نور حالا از نگه داشتنش سر باز زده بود نبودند."),
            StoryParagraph("It touched Diozen — and Diozen began to dissolve.", "به دیوژن خورد — و دیوژن شروع به حل شدن کرد."),
            StoryParagraph("Not into shadow — that would have been a mercy, and he did not deserve mercy — but into nothing, the way a lie dissolves when the truth it has hidden is finally spoken aloud.", "نه به سایه — آن رحمتی می‌بود و او سزاوار رحمت نبود — بلکه به هیچ، همان‌طور که دروغی حل می‌شود وقتی حقیقتی که پنهان کرده بوده، بالاخره بلند گفته می‌شود."),
            StoryParagraph("\"This is not the end,\" Diozen hissed as he faded — and his voice, even as it dissolved, still carried that ancient, patient arrogance. \"I will return.\"", "«این پایان نیست،» دیوژن در حال محو شدن خش‌خش کرد — و صدایش، حتی همان‌طور که حل می‌شد، هنوز آن تکبر کهن و صبور را داشت. «برمی‌گردم.»"),
            StoryParagraph("\"Maybe,\" Arin said — and there was no anger in his voice, no triumph, only a sadness so deep that it had become, in some way, indistinguishable from understanding.", "«شاید،» آرین گفت — و در صدایش خشمی نبود، نه پیروزی، تنها اندوهی چنان عمیق که به‌نحوی، از فهم قابل تفکیک نبود."),
            StoryParagraph("\"But so will we. And as long as we return, so will the light. That is the bargain. That has always been the bargain.\"", "«اما ما هم برمی‌گردیم. و تا وقتی ما برمی‌گردیم، نور هم برمی‌گردد. این معامله است. همیشه همین معامله بوده.»"),
            StoryParagraph("And then Diozen was gone — truly gone, as though he had never existed, as though his ten thousand years had been nothing more than a bad dream from which the world had finally been permitted to wake.", "و بعد دیوژن رفت — به‌راستی رفت، گویی هرگز وجود نداشته، گویی ده هزار سالش چیزی بیش از کابوسی نبوده که جهان بالاخره اجازه‌ی بیدار شدن از آن را یافته بود."),
            StoryParagraph("The fortress collapsed around them — not violently, but gently, the way a house collapses when the people who lived in it have at last moved away.", "قلعه دورشان فرو ریخت — نه با خشونت، بلکه به‌ملایمت، همان‌طور که خانه‌ای فرو می‌ریزد وقتی مردمانی که در آن زندگی می‌کردند بالاخره کوچ کرده باشند."),
            StoryParagraph("They ran outside — Arin and Sara and Kaveh and the six freed guardians — and when they looked up, they saw something they had almost forgotten.", "بیرون دویدند — آرین و سارا و کاوه و شش نگهبان آزادشده — و وقتی به بالا نگاه کردند، چیزی دیدند که تقریباً فراموش کرده بودند."),
            StoryParagraph("The sky was lightening.", "آسمان روشن می‌شد."),
            StoryParagraph("Not quickly, not dramatically, but slowly and patiently — the way the world had always done it, before anyone had thought to ask whether it would continue.", "نه سریع، نه دراماتیک، بلکه آهسته و صبورانه — همان‌طور که جهان همیشه انجامش می‌داد، پیش از آنکه کسی به فکر پرسیدن ادامه یافتنش بیفتد."),
            StoryParagraph("The sun rose over the edge of the world — and the light was so beautiful, so impossibly, unbearably beautiful, that Sara cried, and Kaveh laughed like a young man, and the six freed guardians fell to their knees and wept.", "خورشید از لبه‌ی جهان طلوع کرد — و نور چنان زیبا بود، چنان به‌طرز غیرممکن و غیرقابل تحمل زیبا، که سارا گریست و کاوه مثل جوانی خندید و شش نگهبان آزادشده به زانو افتادند و گریستند."),
            StoryParagraph("And their colors returned to them — not all at once, but one by one, as the light touched them: red, orange, yellow, green, blue, violet — and white.", "و رنگ‌هایشان به آن‌ها بازگشت — نه یک‌جا، بلکه یکی‌یکی، همان‌طور که نور لمسشان می‌کرد: سرخ، نارنجی، زرد، سبز، آبی، بنفش — و سفید."),
            StoryParagraph("The world was alive again.", "جهان دوباره زنده بود."),
            StoryParagraph("And in the years that followed — for there were years, now, there were mornings and evenings and seasons and harvests — they built a new world on the ruins of the old.", "و در سال‌های بعد — چون حالا سال‌ها بود، صبح‌ها و غروب‌ها و فصل‌ها و برداشت‌ها بود — جهانی نو بر ویرانه‌های کهنه ساختند."),
            StoryParagraph("Kaveh trained new guardians — not seven, but hundreds, one in every city, one in every village, one in every heart that was willing.", "کاوه نگهبانان جدید تربیت کرد — نه هفت، بلکه صدها، یکی در هر شهر، یکی در هر روستا، یکی در هر قلبی که حاضر بود."),
            StoryParagraph("Sara found her father, and healed with him the wounds that neither of them had ever permitted the other to see.", "سارا پدرش را یافت و با او زخم‌هایی را درمان کرد که هیچ‌کدام هرگز اجازه نداده بودند دیگری ببیند."),
            StoryParagraph("And Arin — Arin walked from city to city, from village to village, carrying no lantern, holding no shield, wielding no spear.", "و آرین — آرین از شهری به شهر، از روستایی به روستا راه افتاد، نه فانوسی حمل می‌کرد، نه سپری داشت، نه نیزه‌ای می‌چرخاند."),
            StoryParagraph("He carried only the memory of what had happened — and the truth, which he told to everyone who would listen, that the light had never been in a lantern, had never been in a spear, had never been in any object at all.", "تنها خاطره‌ی آنچه گذشته بود را حمل می‌کرد — و حقیقت، که برای هر کسی که گوش می‌داد بازگو می‌کرد، که نور هرگز در فانوسی نبوده، هرگز در نیزه‌ای نبوده، هرگز در هیچ شیئی نبوده است."),
            StoryParagraph("The light is in you, he said. It has always been in you. It will always be in you. You only have to remember.", "نور در توست، می‌گفت. همیشه در تو بوده. همیشه در تو خواهد بود. تنها باید به یاد بیاوری."),
            StoryParagraph("And the people listened — not all of them, never all of them, for there will always be those who prefer the dark — but enough of them, always enough, to keep the light burning.", "و مردم گوش دادند — نه همه‌شان، هرگز همه‌شان، چون همیشه کسانی خواهند بود که تاریکی را ترجیح می‌دهند — اما به‌قدر کافی، همیشه به‌قدر کافی، تا نور روشن بماند."),
            StoryParagraph("The story of Arkadia, of Diozen, of the seven guardians, was told and retold — in kitchens and in temples, in palaces and in hovels — and with every retelling, something of it changed, and something of it remained.", "داستان آرکادیا، دیوژن، هفت نگهبان، گفته و بازگفته شد — در آشپزخانه‌ها و معابد، در کاخ‌ها و کپرها — و با هر بازگویی، چیزی از آن تغییر کرد و چیزی از آن ماند."),
            StoryParagraph("What remained, always, was this: that the light had never been a thing to be found, but a thing to be remembered; never a gift, but a responsibility; never a possession, but a choice.", "آنچه همیشه ماند این بود: که نور هرگز چیزی نبوده که یافته شود، بلکه چیزی بوده که به یاد آورده شود؛ هرگز هدیه‌ای نبوده، بلکه مسئولیتی؛ هرگز تملکی نبوده، بلکه انتخابی."),
            StoryParagraph("And that choice — the choice to remember, the choice to carry, the choice to burn — was one that every person, in every age, had to make for themselves.", "و آن انتخاب — انتخاب به‌یاد آوردن، انتخاب حمل کردن، انتخاب سوختن — انتخابی بود که هر کس، در هر عصر، باید برای خودش می‌گرفت."),
            StoryParagraph("The last guardian of light was not Arin, and had never been Arin; the last guardian of light was whoever, in the darkness, chose to remember.", "آخرین نگهبان نور آرین نبود و هرگز آرین نبوده؛ آخرین نگهبان نور هر کسی بود که در تاریکی، انتخاب می‌کرد به یاد بیاورد."),
            StoryParagraph("And so the story ends — not because there is nothing left to say, but because the ending is not the point.", "و اینگونه داستان پایان می‌یابد — نه چون چیزی برای گفتن نمانده، بلکه چون پایان نکته نیست."),
            StoryParagraph("The point is that there was a beginning — that there is always a beginning — and that beginnings are made, over and over, by people who have decided that the dark will not have the last word.", "نکته این است که آغازی بود — که همیشه آغازی هست — و اینکه آغازها ساخته می‌شوند، بارها و بارها، توسط کسانی که تصمیم گرفته‌اند تاریکی آخرین حرف را نخواهد زد."),
            StoryParagraph("Arin, when he was very old, wrote down the story — all of it, everything you have just read — and he ended it with a single sentence, which he wrote in a hand that had grown shaky with age but that had never lost its clarity.", "آرین، وقتی خیلی پیر شد، داستان را نوشت — همه‌اش، هر چیزی که همین تازه خواندید — و با جمله‌ای یگانه تمامش کرد، که با خطی نوشت که با سن لرزان شده بود اما هرگز شفافیتش را از دست نداده بود."),
            StoryParagraph("The sentence was this: \"When every light dies, keep the lantern burning — but remember that the lantern was never the light.\"", "جمله این بود: «وقتی هر نوری مرد، فانوس را روشن نگه دار — اما یادت باشد که فانوس هرگز نور نبود.»"),
            StoryParagraph("And then, below that sentence, in smaller letters, he wrote the words that would become the motto of every city, every village, every heart that had ever heard his story:", "و بعد، زیر آن جمله، با حروف کوچک‌تر، کلماتی را نوشت که شعار هر شهر، هر روستا، هر قلبی شد که هرگز داستانش را شنیده بود:"),
            StoryParagraph("You are the light. You have always been the light. Now go — and burn.", "تو خودِ نوری. همیشه نور بوده‌ای. حالا برو — و بسوز."),
            StoryParagraph("The end.", "پایان.")
        )
    )
}